-- INSERT preguntas PIR 2025 (convocatoria FSE 2025, Psicología)
-- Fuente: Cuaderno_2025_P_0_C.pdf + Plantilla_Respuestas_FSE_v4.xlsx
-- Generado: 205 preguntas validas de 210 impresas (5 anuladas/en blanco excluidas: 28, 32, 57, 88, 97)
-- especialidad/tema quedan NULL: se clasificaran en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2025) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2025 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

