INSERT INTO public.preguntas
  ("año", numero, especialidad, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2025, 1, NULL, 'Siguiendo el plan terapéutico acordado con nuestro paciente, diseñamos tareas en sesión que exigen integrar información verbal y visual y relacionarla con episodios autobiográficos relevantes. Según el modelo multicomponente de la memoria de trabajo de Baddeley (2012), ¿qué componente resulta clave en este tipo de tareas?:', 'Ejecutivo central.', 'Bucle fonológico.', 'Buffer episódico.', 'Sistema atencional supervisor.', NULL, 'c', NULL, NULL),
  (2025, 2, NULL, 'Durante una valoración neuropsicológica, se administra la lista de palabras del Test de Aprendizaje Auditivo Verbal de Rey (AVLT). Al pedirle a la persona que recuerde las palabras de la lista 2, menciona la palabra “tambor”, que pertenece a la lista 1. ¿Qué fenómeno relacionado con el olvido se está observando?:', 'Interferencia retroactiva.', 'Interferencia proactiva.', 'Interferencia contextual.', 'Inhibición colaborativa.', NULL, 'b', NULL, NULL),
  (2025, 3, NULL, 'Un varón de 24 años refiere en sesión que confunde las señales rojo-verde y que, al conducir de noche, percibe las luces rojas como más apagadas que las verdes. Según la teoría tricromática de la visión, ¿qué alteración explica mejor este patrón perceptivo?:', 'Protanopia.', 'Deuteranopia.', 'Tritanopia.', 'Acromatopsia.', NULL, 'a', NULL, NULL),
  (2025, 4, NULL, 'Un residente comienza a sobrediagnosticar trastorno de estrés postraumático (TEPT) tras haber atendido varios casos graves consecutivos. ¿A qué se puede deber esta sobreestimación de la probabilidad diagnóstica?:', 'Heurístico de Anclaje.', 'Heurístico de Disponibilidad.', 'Heurístico de Representatividad.', 'Heurístico de Simulación.', NULL, 'b', NULL, NULL),
  (2025, 5, NULL, 'Según la teoría motivacional del proceso oponente de Solomon y Corbit (1973, 1974), tras la exposición prolongada a un estímulo ¿qué procesos se producen?:', 'Proceso primario y proceso secundario, ambos de similar intensidad.', 'Proceso A en respuesta al estímulo y proceso B, que genera una reacción opuesta.', 'Proceso A, proceso B y proceso de homoestasis, que equilibra a ambos.', 'Proceso primario, proceso general y proceso sumatorio, de intensidades diferentes.', NULL, 'b', NULL, NULL),
  (2025, 6, NULL, '¿Cómo se denomina al proceso de condicionamiento en el cual el estímulo incondicionado (EI) no se presenta hasta que no ha transcurrido cierto tiempo desde la terminación del estímulo condicionado (EC)?:', 'Condicionamiento de demora.', 'Condicionamiento simultáneo.', 'Condicionamiento de huella.', 'Condicionamiento hacia atrás.', NULL, 'c', NULL, NULL),
  (2025, 7, NULL, '¿Según qué teoría se formarían nuevos conceptos mediante la abstracción de ciertas características que constituyen un prototipo?:', 'Teoría clásica de la formación de conceptos.', 'Modelos mixtos.', 'Teoría probabilística.', 'Teoría del ejemplar.', NULL, 'c', NULL, NULL),
  (2025, 8, NULL, 'Hoy te sientes triste y tienes que estudiar el tema de la depresión y sus síntomas. Observas que tu rendimiento al memorizar este contenido es mayor que otros días. ¿Qué mecanismo podría explicar este efecto?:', 'Memoria dependiente del humor.', 'Carga afectiva del material a recordar.', 'Memoria congruente con el humor.', 'Lo emocional no influye en la memoria.', NULL, 'c', NULL, NULL),
  (2025, 9, NULL, '¿Qué método es utilizado para evaluar el funcionamiento diferencial de los ítems (DIF)?:', 'Samejima.', 'Análisis de distractores.', 'Mantel-Haenszel.', 'Regresión múltiple jerárquica.', NULL, 'c', NULL, NULL),
  (2025, 10, NULL, 'Respecto a la función de información de un ítem en la Teoría de Respuesta al Ítem (TRI), considerando los modelos de 1 y 2 parámetros:', 'Su valor es máximo cuando θ coincide exactamente con el parámetro de dificultad estimado.', 'Su magnitud permanece constante para cualquier valor posible de θ dentro de la escala.', 'Su resultado numérico equivale directamente al error típico de medida.', 'Se obtiene a partir de la pendiente de la curva característica y de la probabilidad acumulada de la distribución normal estándar.', NULL, 'a', NULL, NULL),
  (2025, 11, NULL, 'Entre los diferentes índices de validez de un test diagnóstico, la eficacia del test se refiere a la:', 'Probabilidad de que el resultado del test sea positivo en una persona con el trastorno mental en comparación con una persona sin el trastorno.', 'Proporción de clasificaciones correctas respecto al total de personas evaluadas.', 'Probabilidad de que el resultado del test sea positivo en una persona sin el trastorno mental en comparación con una persona con el trastorno.', 'Proporción de personas sin el trastorno mental correctamente identificadas con un resultado negativo en el test.', NULL, 'b', NULL, NULL),
  (2025, 12, NULL, '¿Qué técnica se utiliza para examinar si la distribución de los datos se ajusta a una distribución teórica (como la distribución normal)?:', 'La prueba de Kolmogorov-Smirnov.', 'La prueba de Mauchly.', 'El test de rachas.', 'La prueba de Levene.', NULL, 'a', NULL, NULL),
  (2025, 13, NULL, 'El enfoque de métodos mixtos dentro de la investigación en psicología clínica permite:', 'Analizar las diferencias globales entre los grupos sin considerar los cambios intraindividuales a lo largo del tiempo, ya que el factor temporal se trata como variable independiente entre individuos.', 'Examinar tanto los efectos principales del grupo y del tiempo como la interacción entre ambos, de modo que es posible determinar si los cambios temporales difieren según la condición experimental asignada.', 'Sustituir procedimientos cuantitativos tradicionales por análisis estadísticos avanzados que permiten interpretar la variabilidad de los datos en muestras reducidas y en entornos clínicos complejos.', 'Combinar estrategias cualitativas y cuantitativas en el mismo estudio, buscando integrar los hallazgos para lograr una comprensión más completa del fenómeno estudiado.', NULL, 'd', NULL, NULL),
  (2025, 14, NULL, 'Un profesional de la psicología clínica desea evaluar la eficacia de un tratamiento de activación conductual en su hospital. Para ello, selecciona aleatoriamente una muestra de pacientes con depresión y forma, también aleatoriamente, dos grupos: experimental y control activo. Tras recoger datos y comparar los grupos obtiene un resultado estadísticamente significativo (p = 0,001). ¿Cuál es la interpretación más adecuada?:', 'El valor p indica que, si en realidad no hubiera diferencias entre los grupos en la población (H0 cierta), la probabilidad de obtener una diferencia como la observada o mayor por azar sería de 0,1%.', 'El valor p indica que, si en realidad no hubiera diferencias entre los grupos en la población (H0 cierta), la probabilidad de que la hipótesis nula sea cierta sería de 0,1%.', 'El valor p indica que, si en realidad no hubiera diferencias entre los grupos en la población (H0 cierta), la probabilidad de que el tratamiento sea eficaz sería de 99,9%.', 'El valor p indica que, si en realidad no hubiera diferencias entre los grupos en la población (H0 cierta), la probabilidad de que la diferencia encontrada sea clínicamente relevante sería de 99,9%.', NULL, 'a', NULL, NULL),
  (2025, 15, NULL, '¿Qué técnica de análisis multivariado tiene como propósito fundamental la búsqueda de una estructura de constructos latentes, a partir de las correlaciones entre las variables observadas?:', 'Análisis discriminante múltiple.', 'Análisis de conglomerados jerárquicos.', 'Regresión logística multinomial.', 'Análisis factorial.', NULL, 'd', NULL, NULL),
  (2025, 16, NULL, 'Un psicólogo clínico atiende en primera consulta a una niña de 7 años cuyos progenitores, divorciados, ostentan su patria potestad. No obstante, el psicólogo clínico es conocedor de que el padre cumple una sentencia condenatoria (orden de alejamiento) por maltrato hacia la madre. ¿Cómo deberá proceder el profesional para recabar el consentimiento informado (CI)?:', 'Deberá obtener el CI de ambos progenitores y citar alternativamente a uno y otro en sesión.', 'Será suficiente con obtener el CI de la madre e informar al padre, con independencia de que el padre conserve la patria potestad.', 'Deberá obtener el CI del adulto acompañante en primera consulta, siempre que dicho adulto esté vinculado por razones de parentesco de primer o segundo grado, ya que en casos de progenitores que cumplen sentencias condenatorias prima el beneficio de la menor.', 'Los servicios de salud mental de la red pública están exentos de obtener el CI de los progenitores en casos de menores expuestos a violencia de género.', NULL, 'b', NULL, NULL),
  (2025, 17, NULL, 'Una psicóloga clínica en ejercicio en el Sistema Nacional de Salud es citada a declarar como testigo-perito ante un tribunal, en relación con un procedimiento penal abierto contra uno de sus pacientes. ¿Cómo debe proceder?:', 'No acudiendo a declarar ante el tribunal, ya que el secreto profesional la exime.', 'Acudiendo al tribunal, pero negándose a declarar aduciendo que la historia clínica de salud mental contiene datos de terceros y apreciaciones subjetivas.', 'Realizando un peritaje previo a la declaración, ya que debe fundamentar la información que proporcione al tribunal en una evaluación psicológica específica.', 'Acudiendo al tribunal, aclarando que sus conclusiones se derivan de la actividad clínica y asistencial mantenida con el paciente.', NULL, 'd', NULL, NULL),
  (2025, 18, NULL, 'En la sala de espera de una psicóloga clínica, dos pacientes comentan sus respectivos seguimientos. Uno de ellos señala que su psicóloga le cita cada dos semanas, mientras que el otro indica que sus revisiones son cada seis meses. Teniendo en cuenta el principio bioético de justicia, ¿cómo debería interpretarse la actuación de la profesional?:', 'Es adecuada, ya que ajustar la frecuencia de las citas en función de las necesidades clínicas de cada paciente constituye una aplicación del principio de justicia entendido como equidad en el trato.', 'Es inadecuada, porque el principio de justicia obliga a tratar a todos los pacientes con la misma periodicidad.', 'Es adecuada, ya que la profesional opta por beneficiar al 50% de sus pacientes, asegurando la paridad de este modo.', 'Es inadecuada, porque la asignación de citas es una cuestión administrativa y no debe depender de criterios clínicos o profesionales.', NULL, 'a', NULL, NULL),
  (2025, 19, NULL, 'Durante la entrevista que se realiza en el proceso de una evaluación psicológica, la empatía es una habilidad básica y necesaria. ¿Cuál de las siguientes alternativas es correcta en relación con el uso de esta habilidad?:', 'La empatía cognitiva hace referencia a la habilidad de sentir con el otro conservando la propia identidad y objetividad.', 'La autorrevelación no es un recurso indicado para transmitir empatía debido a los efectos negativos que puede producir en el paciente.', 'La compasión no ayuda a establecer el rapport necesario para iniciar el proceso de intervención.', 'El terapeuta que transmite pocas autorrevelaciones al paciente puede añadir distancia entre los dos y en el rol que se establece.', NULL, 'd', NULL, NULL),
  (2025, 20, NULL, 'La formulación de caso en evaluación psicológica:', 'Se puede definir como una hipótesis explicativa fundamentada en teoría que organiza la información para planificar y dirigir el tratamiento y evaluar el cambio.', 'Tiene como objetivo principal ordenar datos y orientar el diagnóstico por lo que conviene utilizarla sólo como esquema interno del terapeuta.', 'Constituye el objetivo central de la evaluación, se elabora al inicio y se mantiene esencialmente estable durante el proceso psicoterapéutico.', 'En un enfoque integrador se limita a describir los síntomas actuales en su contexto y no debe incluir diagnóstico psiquiátrico, porque formulación y diagnóstico son incompatibles.', NULL, 'a', NULL, NULL),
  (2025, 21, NULL, 'En el contexto de una entrevista psicológica, ¿qué son los sondeos o pruebas?:', 'Son preguntas que interrogan al entrevistado sobre la justificación de sus acciones.', 'Son una técnica de entrevista verbal no directiva.', 'Son preguntas que animan al entrevistado a expresar sus ideas o sentimientos sobre un problema que ha verbalizado.', 'Son preguntas que ayudan al entrevistado a darse cuenta de las incongruencias de lo que dice o siente.', NULL, 'c', NULL, NULL),
  (2025, 22, NULL, '¿Cuál de las siguientes pruebas NO está incluida en la Batería Cognitiva de Consenso MATRICS (MCCB)?:', 'Trail Making Test (Parte B).', 'Regulación emocional del Test de Inteligencia Emocional Mayer-Salovey-Caruso (MSCEIT).', 'Laberintos de la Neuropsychological Assessment Battery (NAB).', 'Fluidez verbal semántica (animales).', NULL, 'a', NULL, NULL),
  (2025, 23, NULL, 'Tras administrar el Inventario Clínico Multiaxial de Millon-IV (MCMI-IV) a una mujer de 25 años con diagnóstico de anorexia nerviosa, se obtiene una puntuación de Tasa Base (TB) = 87 en el patrón clínico de personalidad evitativa. Este resultado indica que:', 'La TB no es interpretable por sí misma, ya que requiere una transformación a puntuación típica normalizada.', 'La persona evaluada presenta rasgos evitativos por debajo de lo clínicamente significativo.', 'La patología es suficientemente generalizada como para considerar que los rasgos evitativos son clínicamente significativos.', 'La persona evaluada podría no haber contestado con sinceridad puesto que el patrón clínico corresponde a una escala de control del instrumento.', NULL, 'c', NULL, NULL),
  (2025, 24, NULL, 'En la cuarta edición de la Escala de Inteligencia de Wechsler para adultos (WAIS-IV), ¿qué índice se obtiene a partir de las escalas de Comprensión verbal y Razonamiento perceptivo?:', 'El CI total (CIT).', 'El Índice de Capacidad General (ICG).', 'El Índice de Capacidad Cognitiva (ICC).', 'El WAIS-IV no dispone de un índice específico para dichas escalas.', NULL, 'b', NULL, NULL),
  (2025, 25, NULL, 'Respecto a los instrumentos de evaluación de la depresión:', 'Los cuestionarios de evaluación de la depresión pueden sustituir a la entrevista clínica en el diagnóstico de la depresión.', 'La escala de Hamilton para la depresión (HRSD) es útil en la detección de síntomas depresivos, pero no en la monitorización de su evolución.', 'El Inventario de Depresión de Beck en su segunda edición (BDI-II) incluye ítems que evalúan tanto las disminuciones como los aumentos del apetito y del sueño.', 'Una puntuación de 8 puntos se corresponde con depresión leve en el BDI-II.', NULL, 'c', NULL, NULL),
  (2025, 26, NULL, 'En relación con la evaluación de los Estados Mentales de Alto Riesgo (EMAR):', 'Los dos instrumentos más utilizados son la SIPS y la CAARMS.', 'La CAARMS incluye la SOPS, los criterios DSM-IV para el trastorno de la personalidad esquizotípica, un cuestionario de antecedentes familiares y una versión de la GAF.', 'La SOPS es una entrevista semiestructurada desarrollada por el equipo de investigación PRIME de la Universidad de Yale.', 'La SIPS consta de 19 ítems que están organizados en síntomas positivos, negativos, desorganizados y generales.', NULL, 'a', NULL, NULL),
  (2025, 27, NULL, 'En las escalas Wechsler de Inteligencia, ¿cuál de las siguientes subescalas se encuentra simultáneamente en WPPSI-IV, WISC-V y WAIS-IV?:', 'Cubos.', 'Puzzles visuales.', 'Span de dibujos.', 'Búsqueda de símbolos.', NULL, 'a', NULL, NULL),
  (2025, 29, NULL, '¿Qué forma de evaluación se basa en la idea de que todo concepto posee dos tipos de significados complementarios, uno denotativo y otro connotativo?:', 'Listas de adjetivos.', 'Técnica de la rejilla.', 'Diferencial semántico.', 'Clasificaciones Q.', NULL, 'c', NULL, NULL),
  (2025, 30, NULL, 'Indica en cuál de las siguientes baterías de evaluación se incluye, como prueba opcional, el Test Breve de la Evaluación del Estado Cognitivo (BCSE), baremado para el intervalo de edades entre los 1 y 89 años de edad:', 'Escala de Evaluación Cognitiva de Cambridge (CAMCOG-R).', 'Escala de Inteligencia Wechsler para adultos IV (WAIS-IV).', 'Escala de Memoria Wechsler IV (WMS-IV).', 'Programa Integrado de Exploración Neuropsicológica (PIEN - Barcelona).', NULL, 'c', NULL, NULL),
  (2025, 31, NULL, 'La escala DES (Bernstein y Putnam, 1986) mide:', 'Dismorfia corporal.', 'Depresión mayor.', 'Episodios de desregulación emocional.', 'Fenómenos disociativos.', NULL, 'd', NULL, NULL),
  (2025, 33, NULL, '¿Cuál de las siguientes afirmaciones es correcta respecto a la valoración de la sospecha de un trastorno por déficit de atención e hiperactividad (TDAH) en una niña de 11 años mediante los instrumentos SENA, CARAS-R y ENFEN?:', 'El Toulouse-Piéron Revisado facilitaría nueva información.', 'Sería útil añadir pruebas como matrices o semejanzas.', 'El ENFEN no es adecuado por la edad.', 'La aplicación del SENA no es relevante ya que no valora dificultades atencionales.', NULL, 'b', NULL, NULL),
  (2025, 34, NULL, '¿Cuál de las siguientes afirmaciones sobre la depresión infantil es correcta?:', 'En los dibujos de los niños con depresión suele observarse abundancia de detalles con contenido negativo.', 'La concordancia entre informadores (niño, padres, profesores) suele ser baja.', 'El Inventario de Depresión Infantil (CDI) de M. Kovacs consta de dos dimensiones: total depresivo y total positivo.', 'Las rabietas constituyen un síntoma específico de la depresión en edad preescolar.', NULL, 'b', NULL, NULL),
  (2025, 35, NULL, 'Durante una consulta, un niño de 6 años muestra una alteración del comportamiento ante un límite establecido por sus padres: grita, agrede y lanza los juguetes al suelo. ¿Cuál de las siguientes afirmaciones es correcta en relación con el diagnóstico diferencial?:', 'La administración de la Escala VABS-3 de Vineland sería útil para valorar el funcionamiento adaptativo.', 'El dibujo infantil y el juego simbólico permiten determinar con precisión la presencia o ausencia de un trastorno afectivo.', 'Si el comportamiento se reproduce en distintos contextos, el diagnóstico más probable sería un trastorno por déficit de atención con hiperactividad (TDAH).', 'El BASC-3 permitiría llevar a cabo un screening específico de sintomatología TEA.', NULL, 'a', NULL, NULL),
  (2025, 36, NULL, '¿Cuál de estas alteraciones en el lenguaje NO es típica en el trastorno del espectro autista?:', 'Ecolalia.', 'Coprolalia.', 'Inversión pronominal.', 'Escasez de vocabulario.', NULL, 'b', NULL, NULL),
  (2025, 37, NULL, 'Según el DSM-5-TR, el diagnóstico de trastorno por déficit de atención/hiperactividad (TDAH):', 'Puede establecerse conjuntamente con el trastorno del espectro autista (TEA).', 'Requiere que los síntomas hayan aparecido antes de los 7 años de edad.', 'El criterio “con frecuencia es incapaz de jugar o de ocuparse tranquilamente en actividades recreativas” corresponde a un síntoma de inatención.', 'A partir de los 17 años, se requieren al menos seis síntomas de hiperactividad-impulsividad para realizar el diagnóstico.', NULL, 'a', NULL, NULL),
  (2025, 38, NULL, 'Dentro del protocolo de seguimiento del prematuro, ¿qué escala debe usar la psicóloga clínica para evaluar el desarrollo cognitivo, motriz y de la comunicación en niños de edad corregida de 18 meses?:', 'Escala de Brazelton (Brazelton y Nugent, 1997).', 'Escala de Aptitudes Intelectuales (BAS-II; Elliott, Smith y McCullogh, 2011).', 'Escala de inteligencia de Wechsler para preescolar y primaria-IV (WPPSI-IV; Wechsler, 2014).', 'Escalas Bayley de desarrollo infantil – III (Bayley, 2015).', NULL, 'd', NULL, NULL),
  (2025, 39, NULL, 'Lucía es una niña de 8 años que acude a una primera consulta en el Centro de Salud Mental por síntomas obsesivo-compulsivos. Presenta rituales de lavado y pensamientos intrusivos relacionados con la contaminación. Durante el proceso de evaluación, dentro de la entrevista clínica general, ¿qué información sería más relevante recabar para orientar la comprensión funcional de sus síntomas?:', 'Frecuencia y duración de los rituales observados durante la última semana.', 'Presencia de antecedentes médicos o neurológicos relevantes (p.ej., tics).', 'Grado de insight sobre el carácter egodistónico de los síntomas.', 'Posibles ganancias secundarias de los síntomas dentro del contexto familiar.', NULL, 'd', NULL, NULL),
  (2025, 40, NULL, 'La Escala de Funcionamiento Reflexivo para Niños y adolescentes (CRFS) evalúa:', 'La capacidad de comprender e integrar los estados mentales propios y ajenos en el discurso narrativo.', 'La tendencia a resonar emocionalmente con los demás e identificar sus emociones.', 'La habilidad para reconocer conductas observables y explicarlas en función de factores no mentalistas.', 'El grado de control atencional y autorregulación conductual en situaciones sociales.', NULL, 'a', NULL, NULL),
  (2025, 41, NULL, 'Según Vygotski (1934), lenguaje y pensamiento:', 'Son capacidades con orígenes comunes, transmitidas socioculturalmente, y prerrequisitos para el proceso de andamiaje.', 'Tienen orígenes independientes e inician su convergencia por mediación del habla egocéntrica.', 'Tienen orígenes independientes y a lo largo del desarrollo convergen, de modo que el lenguaje se va socializando progresivamente.', 'Son términos empleados para referirse a un mismo proceso, siendo su origen común el habla, transmitida culturalmente, considerándose el pensamiento habla privada fruto de un progresivo proceso de interiorización.', NULL, 'b', NULL, NULL),
  (2025, 42, NULL, 'Al diferenciar entre prerrequisitos y precursores de la teoría de la mente, ¿cuál de las siguientes alternativas corresponde a un precursor de esta capacidad?:', 'Reconocer a los seres humanos como agentes autoanimados e interpretar su conducta como orientada a metas.', 'Comprender los planos conductual y representacional de la intencionalidad.', 'Distinguir entre creencias verdaderas y falsas.', 'Comprender los contenidos proposicionales de las actitudes intencionales.', NULL, 'b', NULL, NULL),
  (2025, 43, NULL, '¿Cuál de las siguientes descripciones sobre las diferentes fases del desarrollo del dibujo planteadas por Luquet es correcta?:', 'En la fase del realismo fortuito existe una relación causal entre el significado y parecido del dibujo y el objeto dibujado.', 'En la fase del realismo frustrado muchos niños dejan de dibujar porque se perciben como poco hábiles al juzgar que su aproximación al modelo no es adecuada.', 'La transparencia y abatimiento son procedimientos que se inician en la fase del realismo visual.', 'En la fase del realismo frustrado el niño se encuentra con obstáculos relacionados con el control motor, limitación atencional e incapacidad sintética.', NULL, 'd', NULL, NULL),
  (2025, 44, NULL, 'Según la Teoría Focal de J. C. Coleman, señale la alternativa INCORRECTA:', 'Cada foco se centra en una dimensión de la identidad.', 'La secuencia de desarrollo no es única ni inmutable.', 'No existen límites claros entre un estadío y el siguiente.', 'La resolución de un aspecto no es requisito imprescindible para el paso al siguiente estadío.', NULL, 'a', NULL, NULL),
  (2025, 45, NULL, 'En los estudios de Tiffany Field sobre la sincronía en el vínculo de apego entre madres e infantes, se observó que los niños respondían con mayor probabilidad a un tipo específico de conducta materna. ¿A cuál nos referimos?:', 'A la imitación del niño.', 'A las pausas.', 'A la conducta espontánea de la madre.', 'A los intentos por captar y mantener la atención del niño.', NULL, 'a', NULL, NULL),
  (2025, 46, NULL, '¿En cuál de las siguientes fases del desarrollo del vínculo afectivo según la Teoría de Bowlby (1969), el bebé selecciona a unas pocas personas para que se conviertan en figuras subsidiarias a la madre y expresa el rechazo a los extraños?:', 'Fase de Orientación y señales sin discriminación de figura.', 'Fase de Orientación y señales dirigidas hacia una o más figuras discriminadas.', 'Fase de Mantenimiento de la proximidad hacia una figura por medio tanto de la locomoción como de señales.', 'Fase de Formación de una asociación con adaptación al objetivo.', NULL, 'c', NULL, NULL),
  (2025, 47, NULL, 'Según la Teoría de las etapas cognoscitivas de Piaget (1936), ¿qué proceso cognitivo estaría utilizando una niña que, teniendo conocimiento de lo que es un pájaro, al ver un avión por primera vez, lo designa como “pájaro”?:', 'Organización.', 'Adaptación.', 'Asimilación.', 'Acomodación.', NULL, 'c', NULL, NULL),
  (2025, 48, NULL, '¿En cuál de los siguientes estadios de la comunicación preverbal (Schaffer, 1984), el bebé accede a la llamada comunicación triádica y aparecen los primeros gestos comunicativos como señalar con el dedo?:', 'Estadio de interés activo por las personas.', 'Estadio de interés por los objetos.', 'Estadio de coordinación de personas y objetos.', 'Estadio de incorporación del lenguaje a la comunicación.', NULL, 'c', NULL, NULL),
  (2025, 49, NULL, 'En psicología diferencial, ¿a qué dos tipos de investigaciones básicas hace referencia el análisis de las fuentes de variabilidad biológica?:', 'El porcentaje de la varianza psicológica explicado por la dotación genética de los individuos y el funcionamiento diferencial de los mecanismos biológicos.', 'El porcentaje de la varianza fenotípica explicado por la dotación genética de los individuos y el funcionamiento diferencial de los mecanismos psicológicos.', 'El porcentaje de la varianza fenotípica explicado por el ambiente de los individuos y el funcionamiento diferencial de los mecanismos biológicos.', 'El porcentaje de la varianza fenotípica explicado por la dotación genética de los individuos y el funcionamiento diferencial de los mecanismos biológicos.', NULL, 'd', NULL, NULL),
  (2025, 50, NULL, 'En el estudio cronométrico de la velocidad mental, ¿cuál de las siguientes es una ventaja del uso del tiempo de inspección frente al tiempo de reacción?:', 'Es una medida compacta que parece implicar más procesos cognitivos.', 'Factores como la motivación, la atención o la personalidad contribuyen sustancialmente a su relación con la inteligencia.', 'No presenta el problema de tener que establecer la ratio velocidad/precisión.', 'Obliga a distinguir entre componentes como el tiempo de decisión y el de movimiento.', NULL, 'c', NULL, NULL),
  (2025, 51, NULL, '¿Qué característica de los rasgos, como unidades de análisis en psicología diferencial, hace referencia a que no son entidades directamente observables, sino que se infieren a través de la observación de indicadores comportamentales representativos del rasgo definido?:', 'Carácter subyacente.', 'Carácter dimensional.', 'Carácter disposicional.', 'Carácter consistente.', NULL, 'a', NULL, NULL),
  (2025, 52, NULL, '¿Cuál de las siguientes afirmaciones es correcta respecto a los resultados de investigaciones longitudinales sobre la estabilidad de la inteligencia a lo largo de la vida?:', 'A grandes rasgos, la estructura jerárquica de la inteligencia varía con la edad.', 'A partir de los 6 años, la estructura de las aptitudes tiende a consolidarse según el modelo jerárquico de tres estratos.', 'El carácter jerárquico de la inteligencia impide que haya cambios en la cantidad de las capacidades intelectuales.', 'En los primeros meses de vida, las diferencias individuales en inteligencia muestran una alta estabilidad predictiva respecto al rendimiento cognitivo posterior.', NULL, 'b', NULL, NULL),
  (2025, 53, NULL, 'Respecto a la regulación identificada en el continuo motivacional propuesto por Ryan y Deci:', 'La persona acepta y valora la actividad, pero a pesar de su relativa autonomía, la actividad no está todavía integrada con los demás aspectos de la experiencia personal.', 'La persona actúa por contingencias externas, como conseguir premios o evitar castigos.', 'La motivación es totalmente autónoma o autorregulada.', 'La persona actúa para evitar la culpa, afirmar su valía o recibir aprobación de los demás.', NULL, 'a', NULL, NULL),
  (2025, 54, NULL, 'En la definición de personalidad propuesta por Costa y McCrae (1994), se postula que deben estar presentes, entre otros, los siguientes aspectos. Señale el INCORRECTO:', 'Los sistemas psicofísicos, que representan las tendencias y capacidades básicas del individuo.', 'Las necesidades básicas o sistemas de motivación que impulsan la conducta.', 'La biografía objetiva, entendida como el conjunto de acontecimientos significativos en la vida de cada persona.', 'El autoconcepto, es decir, el sentido de identidad personal del individuo.', NULL, 'b', NULL, NULL),
  (2025, 55, NULL, '¿Qué dimensión está incluida en el factor de propensión general a la psicopatología (factor p) de Caspi et al. (2014)?:', 'Desórdenes del pensamiento.', 'Tendencia a la ansiedad.', 'Tendencia a la depresión.', 'Conductas antisociales.', NULL, 'a', NULL, NULL),
  (2025, 56, NULL, '¿Por cuál de los siguientes motivos se considera la obra de Huarte de San Juan como un antecedente del estudio científico de las diferencias individuales?:', 'Puso en relación las diferencias en determinadas características de las personas con aquellas habilidades que les correspondería desarrollar.', 'Distinguió entre habilidades naturales y aprendidas.', 'Realizó la división entre intelecto, emoción y volición.', 'Hizo referencia a la amplitud de las diferencias individuales en variables mensurables a partir de una metodología científica y bajo una orientación marcadamente genetista.', NULL, 'a', NULL, NULL),
  (2025, 58, NULL, 'La investigación sobre autoeficacia indica que una baja percepción de competencia personal contribuye al desarrollo de síntomas depresivos porque:', 'Aumenta la probabilidad de atribuciones externas incontrolables.', 'Favorece la rumiación y la anticipación negativa de resultados.', 'Reduce la activación fisiológica necesaria para la acción.', 'Incrementa la dependencia de factores situacionales externos.', NULL, 'b', NULL, NULL),
  (2025, 59, NULL, 'Según la teoría de la motivación de logro de Atkinson (1957), la elección de tareas en sujetos con alta necesidad de logro se caracteriza porque:', 'Prefieren tareas muy fáciles, ya que garantizan el éxito y refuerzan su autoconfianza.', 'Prefieren tareas de dificultad intermedia, ya que maximizan la probabilidad de éxito con una adecuada satisfacción derivada de la superación.', 'Prefieren tareas muy difíciles, porque el elevado riesgo de fracaso aumenta el valor incentivo del éxito.', 'Suelen evitar tareas evaluadas mediante autoinformes, dado que estas no reflejan los motivos implícitos de logro.', NULL, 'b', NULL, NULL),
  (2025, 60, NULL, 'Los estudios sociohistóricos de la personalidad realizados por Jean Twenge (2000, 2001) indican que el incremento del Neuroticismo/Ansiedad se asocia con:', 'Una disminución del individualismo.', 'Cambios en el estilo educativo orientados hacia una mayor permisividad.', 'Un incremento en la movilidad de la población y globalización.', 'Un aumento del número de personas que viven solas y disminución de la tasa de nacimientos.', NULL, 'd', NULL, NULL),
  (2025, 61, NULL, '¿Cuál es la anomalía neurobiológica que mejor explica la dislexia del desarrollo, según los hallazgos en estudios post mortem y de neuroimagen?:', 'Una disminución generalizada en el volumen de la corteza cerebral, afectando las áreas motoras y el cerebelo.', 'Un incremento en la actividad de las áreas posteriores del cerebro (occipito-temporal) en comparación con los lectores normales.', 'Trastornos en la migración neuronal (ectopias y dislaminación de capas corticales) y una reducción en la asimetría normal del Planum Temporale izquierdo.', 'Un déficit en el procesamiento visual auditivo causado por la hipoactivación de la corteza prefrontal medial.', NULL, 'c', NULL, NULL),
  (2025, 62, NULL, 'La hipótesis del marcador somático, propuesta por A. Damasio, sugiere que:', 'Las decisiones se toman a través de procesos racionales, sin influencia emocional.', 'Las sutiles modificaciones corporales (marcadores somáticos) reflejan estados emocionales que guían la toma de decisiones, especialmente en situaciones con incertidumbre moral o ética.', 'El daño en la corteza orbitofrontal mejora la toma de decisiones al eliminar la influencia de las emociones.', 'La capacidad de recordar eventos autobiográficos específicos a largo plazo está alterada.', NULL, 'b', NULL, NULL),
  (2025, 63, NULL, '¿Qué hormona segregada por los testículos durante el desarrollo embrionario impide la formación del sistema de Müller (precursor de los órganos sexuales femeninos)?:', 'Testosterona.', 'Dihidrotestosterona.', 'Inhibina.', 'Hormona antimülleriana.', NULL, 'd', NULL, NULL),
  (2025, 64, NULL, 'Según los hallazgos neuropsicológicos (como el caso H.M.), ¿cuál es el papel principal del hipocampo en el proceso mnésico?:', 'Es esencial para la codificación inicial y la consolidación de nuevos recuerdos declarativos (recuerdos episódicos y también recuerdos semánticos), aunque no es el almacén final.', 'Es el almacén primario de todos los recuerdos a largo plazo, sean declarativos o procedimentales.', 'Se encarga de la manipulación activa de la información a corto plazo, facilitando la memoria de trabajo.', 'Media la expresión de las respuestas emocionales inconscientes, como el condicionamiento del miedo.', NULL, 'a', NULL, NULL),
  (2025, 65, NULL, '¿En cuáles de las siguientes funciones está especialmente implicado el hipotálamo?:', 'Regular la actividad simpática y parasimpática, decidir si se activan procesos atencionales automáticos o controlados y regular el metabolismo alimentario.', 'Facilitar la comunicación entre el sistema nervioso y el sistema endocrino, regular la actividad simpática y parasimpática y controlar el metabolismo hídrico.', 'Realizar la integración motora, el relevo sensorial y la valoración afectiva en la percepción de caras.', 'Controlar los ritmos circadianos, la coordinación motora y la consolidación de la memoria.', NULL, 'b', NULL, NULL),
  (2025, 66, NULL, '¿Cuál es el lugar principal de producción del líquido cefalorraquídeo (LCR)?:', 'La sustancia blanca cerebral.', 'El espacio subaracnoideo.', 'Los plexos coroideos.', 'Las vellosidades aracnoideas.', NULL, 'c', NULL, NULL),
  (2025, 67, NULL, '¿Cuál es la característica clínica fundamental que permite diferenciar las afasias transcorticales (tanto motora como sensorial) de las perisilvianas (Broca y Wernicke)?:', 'En las transcorticales está afectada la repetición del lenguaje oído; esta función se mantiene en las perisilvianas.', 'En las transcorticales está preservada la repetición del lenguaje oído; esta función está afectada en las perisilvianas.', 'En las transcorticales está afectada la conciencia de las dificultades (hay anosognosia); esta función se mantiene en las perisilvianas.', 'En las transcorticales está preservada la conciencia de las dificultades; esta función está afectada en las perisilvianas (hay anosognosia).', NULL, 'b', NULL, NULL),
  (2025, 68, NULL, 'El circuito de activación por defecto (CAD) o red neuronal por defecto:', 'Se desarrolla y madura muy tempranamente en la etapa infantil, quedando completo su desarrollo madurativo entre los 2 y los 4 años.', 'Es una red centrada en zonas posteriores del cerebro, y no implica al córtex prefrontal.', 'Se produce únicamente cuando la persona entra en meditación/relajación profunda y consigue dejar la mente en blanco y no pensar.', 'Puede estar activada mientras la persona divaga y fantasea con el futuro.', NULL, 'd', NULL, NULL),
  (2025, 69, NULL, '¿Cuál es la distinción funcional principal entre la apraxia ideomotora y la apraxia ideatoria?:', 'La apraxia ideatoria se caracteriza por la incapacidad de realizar gestos intransitivos o simbólicos, a diferencia de la apraxia ideomotora, que afecta únicamente a gestos transitivos.', 'La apraxia ideomotora es un déficit en la programación espaciotemporal de los movimientos aprendidos, mientras que la ideatoria es un trastorno en la concepción de las secuencias de actos o en el conocimiento del uso de objetos.', 'La apraxia ideomotora aparece tras lesiones frontales del hemisferio izquierdo, mientras que la apraxia ideatoria está ligada exclusivamente a lesiones subcorticales.', 'La apraxia ideatoria tiene conservadas las fórmulas motoras mientras que en la apraxia ideomotora están alteradas.', NULL, 'b', NULL, NULL),
  (2025, 70, NULL, '¿Cómo se denomina la prueba utilizada en la evaluación preoperatoria antes de la cirugía de la epilepsia, destinada a determinar la lateralización del lenguaje y evaluar el riesgo de amnesia, que se realiza habitualmente mediante la inyección intracarotídea de amital sódico para producir una anestesia selectiva de cada hemisferio cerebral?:', 'Test de Wada.', 'Test de Harris.', 'Test de Edimburgo.', 'Test de lateralidad Martin-Lobo.', NULL, 'a', NULL, NULL),
  (2025, 71, NULL, '¿Qué evento ocurre inmediatamente después de la entrada de iones de Calcio (Ca 2+) al botón terminal durante la transmisión sináptica química?:', 'La despolarización de la membrana postsináptica.', 'La unión de los neurotransmisores a los receptores postsinápticos.', 'La degradación enzimática del neurotransmisor.', 'La movilización de las vesículas sinápticas hacia la membrana.', NULL, 'd', NULL, NULL),
  (2025, 72, NULL, 'En el síndrome de Korsakoff:', 'La memoria episódica y la semántica están igualmente alteradas tanto en la fase anterógrada como retrógrada, lo que resulta en un deterioro cognitivo global.', 'La amnesia anterógrada es moderada y la capacidad de adquirir nueva información solo se ve levemente afectada, mientras que la amnesia retrógrada es total.', 'La amnesia retrógrada no presenta un gradiente temporal, afectando por igual a los sucesos de la infancia y a los recientes.', 'La amnesia anterógrada para registrar nuevos hechos es severa, a pesar de que la memoria semántica se mantiene conservada.', NULL, 'd', NULL, NULL),
  (2025, 73, NULL, '¿Cuál de los siguientes trastornos tiene como uno de los criterios centrales la presencia de alucinaciones visuales complejas recurrentes, bien formadas y detalladas, además de signos motores espontáneos de parkinsonismo?:', 'Enfermedad de Parkinson.', 'Demencia frontotemporal.', 'Demencia con cuerpos de Lewy.', 'Corea de Huntington.', NULL, 'c', NULL, NULL),
  (2025, 74, NULL, 'La heminegligencia:', 'Es un término que se puede utilizar como sinónimo de la hemianopsia ipsilateral y es muy poco frecuente.', 'Cursa con la parálisis motora de los miembros superiores o inferiores.', 'El paciente es consciente de sus propios déficits y tiende a corregirlos espontáneamente, realizando movimientos compensatorios para poder tener en cuenta todo el campo visual.', 'Suele presentarse en pacientes que han sufrido daño cerebral en el lóbulo parietal derecho.', NULL, 'd', NULL, NULL),
  (2025, 75, NULL, '¿En qué trastorno afásico los pacientes muestran un habla normal al repetir, una comprensión auditiva muy deteriorada y fluidez muy pobre en la emisión espontánea?:', 'Afasia de Broca.', 'Afasia motora transcortical.', 'Afasia transcortical mixta.', 'Afasia global.', NULL, 'c', NULL, NULL),
  (2025, 76, NULL, '¿Cuál de los siguientes es uno de los factores comunes de las terapias familiares sistémicas?:', 'Alterar la visión de la familia sobre el problema, para que esté más contextualizada y tenga una lógica lineal.', 'Explicitar y hacer circular la experiencia emocional interna, habitualmente no compartida.', 'Aumentar la frecuencia de las interacciones diádicas, como vía principal de cambio dentro del sistema.', 'Disminuir la tasa de interacciones metacomunicativas.', NULL, 'b', NULL, NULL),
  (2025, 77, NULL, 'En la terapia de esquemas de Young, ¿cuál de las siguientes descripciones se corresponde con la función que cumple el modo del adulto sano?:', 'Promover la autorregulación emocional a través del control cognitivo y la evitación de emociones desbordantes.', 'Integrar y moderar a los modos disfuncionales.', 'Reducir la intensidad de los esquemas mediante la confrontación racional de las creencias nucleares.', 'Mantener la estabilidad del sistema de modos reforzando las conductas de afrontamiento sobrecompensatorio.', NULL, 'b', NULL, NULL),
  (2025, 78, NULL, 'Castonguay et al. (2019) han propuesto diferentes principios asociados al cambio en psicoterapia y los han organizado en varias categorías. ¿En cuál de ellas se incluirían las preferencias del paciente y su estilo de afrontamiento?:', 'Factores relacionados con el pronóstico del paciente.', 'Factores moderadores del paciente.', 'Factores relacionados con variables de proceso del paciente.', 'Factores asociados a la relación terapéutica.', NULL, 'b', NULL, NULL),
  (2025, 79, NULL, 'Una psicóloga clínica que trabaja en un dispositivo de atención a las adicciones, al final de cada sesión, dedica un tiempo a preguntar a los pacientes qué opinan del método que están siguiendo en la terapia, si las sesiones les resultan útiles y si se han sentido comprendidos por ella. ¿Qué tipo de práctica está llevando a cabo?:', 'Una adaptación a los estadios de cambio del modelo de Prochaska y DiClemente.', 'La reparación de rupturas en la alianza terapéutica.', 'La entrevista motivacional.', 'La obtención de feedback sobre el proceso terapéutico.', NULL, 'd', NULL, NULL),
  (2025, 80, NULL, '¿Cómo se denomina a la estereotipia verbal en la que el paciente repite palabras o sílabas de su propio discurso?:', 'Palilalia.', 'Ecolalia.', 'Perseveración semántica.', 'Taquifemia.', NULL, 'a', NULL, NULL),
  (2025, 81, NULL, 'A diferencia del descarrilamiento, el paciente con discurso circunstancial:', 'Alcanza el propósito del discurso con paréntesis escasos o inexistentes.', 'Hace uso de excesivos paréntesis en respuesta a estímulos no inmediatos.', 'Da gran cantidad de detalles e información anómala por su carácter perseverante.', 'Proporciona detalles que, aunque irrelevantes, guardan alguna relación con el tema principal.', NULL, 'd', NULL, NULL),
  (2025, 82, NULL, 'El paciente amnésico:', 'Suele expresar su memoria de forma consciente y precisa para hechos recientes, aunque olvida los remotos.', 'Muestra dificultades para conectar de forma significativa unidades amplias de información.', 'Muestra un mayor deterioro en tareas de memoria implícita (p.ej., priming o aprendizaje motor) que en tareas explícitas de recuerdo consciente.', 'Presenta una alteración generalizada de la memoria semántica, manteniendo conservada la capacidad para recordar experiencias personales y su contexto.', NULL, 'b', NULL, NULL),
  (2025, 83, NULL, 'Según Farina et al. (2019), ¿cuál de los siguientes enunciados refleja con mayor precisión la distinción entre disociación y desintegración?:', 'La disociación describe una desconexión gradual entre afecto y cognición, mientras que la desintegración especifica fallos generalizados en la memoria autobiográfica.', 'La desintegración afecta a la conectividad cerebral y las funciones integradoras de alto orden, mientras que la disociación supone una recomposición funcional en sistemas psíquicos diferenciados.', 'Desde una perspectiva integradora, el término desintegración se reserva a fenómenos somáticos y el de disociación a fenómenos cognitivos.', 'La disociación refleja un proceso regresivo de tipo emocional, mientras que la desintegración corresponde a alteraciones estructurales del sistema nervioso central.', NULL, 'b', NULL, NULL),
  (2025, 84, NULL, 'Una mujer de 34 años con antecedentes de maltrato infantil relata que, tras discutir con su pareja, siente que “una parte de mí se desconecta y actúa sola”. En esos momentos adopta un tono agresivo y luego no recuerda bien lo sucedido. Entre episodios, funciona con normalidad en su trabajo y relaciones. Según la teoría de la disociación estructural de la personalidad (Van der Hart et al., 2006), ¿cuál es la explicación oportuna de este patrón?:', 'Episodio disociativo por activación del sistema vagal dorsal, con desconexión ante la amenaza interpersonal.', 'Alternancia entre una personalidad aparentemente normal (PAN) y una parte emocional (PE) fijada en recuerdos traumáticos no integrados.', 'Despersonalización secundaria con distorsión perceptiva, pero conservación de la continuidad del self.', 'Activación parcial de partes disociativas menores dentro de la PAN, sin división estructural del self.', NULL, 'b', NULL, NULL),
  (2025, 85, NULL, 'Según la CIE-11, el trastorno de disforia por la integridad corporal se caracteriza por un deseo intenso y persistente de tener una discapacidad física importante, que se acompaña de una incomodidad persistente con, o de sentimientos negativos intensos hacia:', 'El funcionamiento o la configuración actual del propio cuerpo.', 'La imposibilidad de cumplir roles sociales esperados en función del género o la edad.', 'La presencia de una apariencia corporal considerada socialmente inadecuada o imperfecta.', 'El temor persistente a padecer una enfermedad grave asociada a la pérdida de la función corporal.', NULL, 'a', NULL, NULL),
  (2025, 86, NULL, 'M., de 47 años, vive rodeada de grandes cantidades de objetos cotidianos sin valor (envases, ropa usada, el agua usada de la bañera). No los guarda deliberadamente, ni adquiere nuevos, y le resulta muy difícil deshacerse de los que ya tiene, generando gran malestar. Según la CIE-11, este patrón corresponde a:', 'Conductas de conservación precautoria.', 'Conductas activas de acumulación.', 'Evitación ansiosa ante la pérdida de control.', 'Conductas pasivas de acumulación.', NULL, 'd', NULL, NULL),
  (2025, 87, NULL, 'Como señalan Abramowitz et al. (2018), la eficacia de la exposición con prevención de respuesta (EPR) en el tratamiento del TOC se explica principalmente porque:', 'La exposición produce la extinción del miedo condicionado mediante la habituación progresiva.', 'Refuerza la tolerancia a la ansiedad por medio de la repetición y la fatiga fisiológica.', 'Favorece la incorporación de nueva información que modifica la estructura del miedo y genera una nueva relación inhibitoria entre los estímulos temidos y la ausencia de amenaza.', 'Su eficacia depende de la reducción gradual de la evitación y de las conductas de neutralización.', NULL, 'c', NULL, NULL),
  (2025, 89, NULL, 'Según el modelo de creencias de salud, ¿qué determina la amenaza percibida de la enfermedad?:', 'La susceptibilidad y gravedad percibida y las claves para la acción.', 'Las creencias sobre la enfermedad que haya desarrollado la persona.', 'La creencia de la capacidad que tiene el sujeto para superar la enfermedad.', 'La vulnerabilidad a desarrollar una enfermedad según los antecedentes familiares.', NULL, 'a', NULL, NULL),
  (2025, 90, NULL, '¿Cuál de los siguientes NO es un factor protector frente al desarrollo de un síndrome postcuidados intensivos familiar (SPCI-F)?:', 'Edad avanzada del paciente.', 'Creencias religiosas o espirituales fuertes.', 'Sensación de control percibida.', 'Rol pasivo en la toma de decisiones.', NULL, 'd', NULL, NULL),
  (2025, 91, NULL, 'En relación con la regulación emocional en los trastornos mentales, ¿en cuál se observa una reactividad emocional especialmente intensa y duradera ante acontecimientos negativos, junto con una respuesta atenuada ante los positivos?:', 'Trastornos depresivos.', 'Trastornos de ansiedad.', 'Trastornos de estrés postraumático.', 'Trastorno límite de personalidad.', NULL, 'a', NULL, NULL),
  (2025, 92, NULL, 'Según el modelo de continuo psicótico propuesto por Van Os y Kapur (2009), ¿qué dimensiones se plantean como componentes en su visión transdiagnóstica de los trastornos psicóticos?:', 'Dimensión psicótica, desorganizada, negativa y afectiva.', 'Dimensión positiva, negativa y desorganizada.', 'Dimensión positiva, negativa, depresiva, maníaca y mixta.', 'Dimensión sintomática, conductual y afectiva.', NULL, 'a', NULL, NULL),
  (2025, 93, NULL, 'Ante un paciente que presenta delirios y alucinaciones, ¿cuál de las siguientes sería la actitud más adecuada del terapeuta?:', 'Usar preguntas directas para poder establecer lo antes posible un análisis funcional de la experiencia psicótica.', 'Utilizar un lenguaje técnico y preciso para que el paciente confíe en la capacidad del terapeuta para ayudarlo.', 'Preguntar al paciente si está dispuesto a hablar de una posible mala interpretación de los fenómenos y el efecto que las experiencias resultantes han tenido en su vida.', 'Centrar al paciente en un debate cognitivo sobre sus interpretaciones y estar atento a sus intentos de evitar el tema, para no reforzarlo negativamente.', NULL, 'c', NULL, NULL),
  (2025, 94, NULL, '¿Cuáles son consideradas características básicas de la anorexia nerviosa?:', 'Restricción de la ingesta, miedo a ganar peso o a engordar y sensación de ineficacia.', 'Alteración de la imagen corporal, miedo intenso a ganar peso o a engordar y restricción de la ingesta.', 'Preocupación por comer en público que conduce a restricción de la ingesta, sensación de ineficacia y pensamiento inflexible.', 'Bajo peso, pensamiento inflexible y miedo a ganar peso o engordar.', NULL, 'b', NULL, NULL),
  (2025, 95, NULL, 'Señale la respuesta correcta con respecto a la bulimia nerviosa:', 'El trastorno se produce frecuentemente en personas con obesidad.', 'Las irregularidades menstruales o la amenorrea se producen a menudo en las mujeres con bulimia nerviosa.', 'No se han encontrado evidencias de que la bulimia nerviosa pueda dar lugar a problemas cardíacos.', 'Solo una minoría de pacientes con anorexia nerviosa migra a diagnóstico de bulimia nerviosa.', NULL, 'b', NULL, NULL),
  (2025, 96, NULL, '¿A qué hace referencia literalmente el término anorexia?:', 'Falta de apetito.', 'Nula ingesta de alimentos.', 'Bajo peso.', 'Restricción alimentaria voluntaria.', NULL, 'a', NULL, NULL),
  (2025, 98, NULL, 'De acuerdo con el DSM-5, ¿qué diagnóstico recibiría una persona que presenta purgas recurrentes para influir en el peso o forma corporales (p.ej., vómitos autoprovocados), como promedio al menos una vez a la semana durante 3 meses y en ausencia de otros comportamientos de interés clínico?:', 'Bulimia Nerviosa, gravedad leve.', 'Bulimia Nerviosa, gravedad moderada.', 'Ortorexia Nerviosa.', 'Se incluiría en la categoría “Otro trastorno alimentario o de la ingestión especificado”.', NULL, 'd', NULL, NULL),
  (2025, 99, NULL, 'Respecto al tratamiento de la anorexia nerviosa:', 'No existe ningún fármaco que sea eficaz para tratar la sintomatología principal.', 'El abordaje terapéutico está marcado por dos factores centrales de su psicopatología: la demacración del peso y la egodistonía del trastorno.', 'No se recomienda el uso de suplementos nutricionales.', 'La terapia psicodinámica está contraindicada en pacientes con anorexia nerviosa.', NULL, 'a', NULL, NULL),
  (2025, 100, NULL, 'En el tratamiento de las parasomnias:', 'La terapia de ensayo en imaginación (IRT) es una variante de la desensibilización sistemática específica para trabajar las pesadillas.', 'Para el tratamiento de las pesadillas, la aplicación de la terapia de ensayo en imaginación (IRT) suele ser en formato individual.', 'En el caso de los terrores nocturnos o sonambulismo, se recomienda a los familiares que despierten al paciente para reducir la excitación o confusión de la persona.', 'Para el tratamiento de los terrores nocturnos, lo primero sobre lo que se debe intervenir es sobre los factores precipitantes.', NULL, 'd', NULL, NULL),
  (2025, 101, NULL, 'En los trastornos del sueño:', 'El trastorno de comportamiento del sueño REM es a menudo un indicador de trastornos neurodegenerativos como la enfermedad de Parkinson.', 'Los trastornos del sueño suelen presentarse en ausencia de otras afecciones clínicas.', 'La narcolepsia es un trastorno asociado a alteraciones en el sistema nervioso periférico.', 'Los trastornos del sueño tienen una baja prevalencia.', NULL, 'a', NULL, NULL),
  (2025, 102, NULL, 'En la narcolepsia:', 'El resultado del test de latencias múltiples del sueño es positivo en un 2-4% de personas con narcolepsia.', 'En los episodios de cataplejía se da una pérdida brusca bilateral del tono muscular y de la consciencia, que se desencadenan con la risa o las bromas.', 'Se asocia a un aumento del índice de masa corporal u obesidad.', 'Pueden ser frecuentes las alucinaciones hipnopómpicas (vividas antes de dormir o al quedarse dormidos) o hipnagógicas (justo después de despertarse).', NULL, 'c', NULL, NULL),
  (2025, 103, NULL, '¿En cuál de los siguientes trastornos del sueño es característica una alteración prolongada de la alerta en la transición sueño-vigilia, en la que la persona parece despierta, pero hay una disminución de la habilidad motora, conducta inapropiada y pueden aparecer déficits de memoria, desorientación temporoespacial y sensación de mareo?:', 'Trastorno de hipersomnia.', 'Trastorno del despertar del sueño no REM.', 'Narcolepsia.', 'Trastorno de la conducta del sueño REM.', NULL, 'a', NULL, NULL),
  (2025, 104, NULL, 'Según la CIE-11, ¿cuál de las siguientes afirmaciones define de forma correcta el término comportamiento suicida y lo diferencia de fenómenos relacionados?:', 'Episodio específico de conducta autodestructiva emprendida con la intención consciente de poner fin a la propia vida.', 'Pensamientos, ideas o rumiaciones sobre la posibilidad de acabar con la vida de uno, que va desde pensar en estar muerto hasta la formulación de planes elaborados.', 'Acciones concretas, como la compra de un arma o el almacenamiento de medicamentos, que se realizan para cumplir el deseo de terminar con la propia vida, pero que de por sí, no constituyen un intento de suicidio.', 'Lesiones autoinfligidas intencionales en el cuerpo (cortes, raspaduras quemaduras, mordeduras), con la expectativa de que la lesión solo conducirá a un daño físico menor.', NULL, 'c', NULL, NULL),
  (2025, 105, NULL, 'Dentro del marco ideación-a-acción en la conducta suicida, se han propuesto teorías que diferencian entre los procesos psicológicos que generan ideación y los que explican la transición de la ideación al intento de suicidio. ¿Cuál de las siguientes teorías NO forma parte de este enfoque?:', 'Teoría interpersonal de T. Joiner.', 'Modelo de desesperanza de A. Beck.', 'Modelo integrado motivacional-volitivo del suicidio de O`Connor.', 'Teoría de los tres pasos de Klonsky y May.', NULL, 'b', NULL, NULL),
  (2025, 106, NULL, 'En relación a la paradoja de género en la conducta suicida, es correcta:', 'Hombres y mujeres presentan tasas similares de suicidio consumado, pero las mujeres presentan más intentos.', 'No existen diferencias estadísticamente significativas en las tasas de mortalidad por suicidio en el mundo atendiendo únicamente al género.', 'La mayor tasa de mortalidad por suicidio en el hombre ocurre exclusivamente en la franja etaria 40-59 años, no existiendo estas diferencias en otras edades.', 'Los hombres presentan tasas más altas de suicidio consumado, mientras que las mujeres presentan más intentos de suicidio.', NULL, 'd', NULL, NULL),
  (2025, 107, NULL, 'F. lleva ingresado en una unidad de hospitalización breve más de 3 meses tras ser diagnosticado de un trastorno depresivo mayor recurrente. En las últimas semanas se aprecia una notable disminución en sus expresiones emocionales, escaso contacto afectivo con los compañeros y un tono general de frialdad ante noticias o acontecimientos personales. En cuanto a su afectividad, podría decirse que F. presenta:', 'Distimia.', 'Rigidez afectiva.', 'Abulia.', 'Indiferencia afectiva.', NULL, 'd', NULL, NULL),
  (2025, 108, NULL, 'Una paciente acude a consulta refiriendo episodios recurrentes que describe como “ataques de ansiedad”. Durante ellos experimenta taquicardia, sensación de tensión y dificultad para controlar su impulso de gritar o golpear objetos. Además, durante la crisis la paciente siente que si no descarga esa energía podría “explotar” físicamente. Las crisis no se acompañan de miedo a perder el control o a que ocurra algo catastrófico, y suelen aparecer en contextos de frustración o discusiones con su pareja. El fenómeno descrito se corresponde a:', 'Ataques de ira.', 'Crisis de angustia.', 'Crisis disociativas.', 'Crisis de ansiedad generalizada.', NULL, 'a', NULL, NULL),
  (2025, 109, NULL, 'Según el programa de Chóliz y Marcos (2020), ¿cuál de los siguientes objetivos NO es de la fase inicial de tratamiento para la adicción a los videojuegos?:', 'Analizar la adicción al juego desde una perspectiva biopsicosocial.', 'Ofrecer información sobre el juego y sus consecuencias.', 'Analizar si precisa intervención en otras áreas.', 'Conseguir que el paciente admita que tiene un problema con el juego.', NULL, 'b', NULL, NULL),
  (2025, 110, NULL, '¿Qué componente ejecutivo se encuentra especialmente alterado en el trastorno depresivo mayor y se asocia con modos de procesamiento de la información y estrategias de regulación emocional en las alteraciones del estado de ánimo?:', 'Flexibilidad cognitiva.', 'Inhibición cognitiva.', 'Memoria de trabajo.', 'Control cognitivo.', NULL, 'd', NULL, NULL),
  (2025, 111, NULL, 'La hipótesis de la amortiguación en relación al efecto del apoyo social sobre la salud plantea que:', 'El apoyo social instrumental tiene siempre un efecto positivo y directo sobre la salud.', 'El apoyo social mitiga los daños sobre la salud que produce la exposición al estrés.', 'Las personas con buen apoyo social desarrollan menos conductas perjudiciales para la salud.', 'El apoyo social facilita la realización de conductas promotoras de la salud.', NULL, 'b', NULL, NULL),
  (2025, 112, NULL, '¿Cuál de los siguientes errores cognitivos planteados por Beck (1979/1983) tiene un mayor nivel de consistencia según la evidencia disponible en el trastorno depresivo mayor?:', 'Abstracción selectiva.', 'Sesgos negativos interpretativos.', 'Inferencias arbitrarias.', 'Sobregeneralización.', NULL, 'b', NULL, NULL),
  (2025, 113, NULL, 'En los trastornos depresivos, a diferencia de los trastornos bipolares, es más típico:', 'Una menor frecuencia de fracaso en las relaciones de pareja.', 'Una mayor frecuencia de síntomas atípicos.', 'Una menor frecuencia de quejas somáticas.', 'Una mayor ocurrencia de episodios depresivos en el periparto.', NULL, 'a', NULL, NULL),
  (2025, 114, NULL, '¿Qué afirmación es correcta con respecto a la Terapia Interpersonal de Klerman y Weissman (1984, 2018) para el tratamiento de la depresión mayor en adultos?:', 'Incluye la reestructuración cognitiva de creencias que puedan influir en las áreas problemáticas detectadas a nivel interpersonal.', 'Entiende la depresión como una enfermedad médica con etiología neuroquímica cuyo mantenimiento se debe a cambios en el entorno interpersonal.', 'En caso de detectar varias áreas problemáticas implicadas, se recomienda un abordaje secuencial.', 'Es una terapia pragmática y empírica que ofrece un marco comprensivo completo de la depresión.', NULL, 'c', NULL, NULL),
  (2025, 115, NULL, 'En el trastorno de depresión mayor, según el DSM-5-TR:', 'El curso de la depresión podría reflejar la adversidad sociocultural que se asocia a la pobreza, el racismo y la marginalización.', 'Los varones refieren más síntomas atípicos de la depresión que las mujeres.', 'La recuperación de un episodio depresivo mayor se inicia dentro de los 3 meses siguientes al comienzo en el 30% de los individuos.', 'La probabilidad de suicidio consumado disminuye durante la época de la adultez media y tardía.', NULL, 'a', NULL, NULL),
  (2025, 116, NULL, '¿Cuál de las siguientes descripciones es correcta en relación con la evolución del trastorno de síntomas neurológicos funcionales?:', 'El pronóstico suele ser favorable, con resolución completa en la mayoría de los casos.', 'La larga duración de los síntomas constituye un factor de buen pronóstico.', 'El diagnóstico y la edad tempranos parecen predecir un buen resultado.', 'Los ataques psicógenos no epilépticos mejoran espontáneamente en la mayoría de los pacientes.', NULL, 'c', NULL, NULL),
  (2025, 117, NULL, '¿Cuál de los siguientes elementos transdiagnósticos NO se ha postulado como variable común en los trastornos por preocupaciones somáticas?:', 'Amplificación somatosensorial.', 'Perfeccionismo orientado a la salud.', 'Intolerancia a la incertidumbre.', 'Pensamiento rumiativo.', NULL, 'b', NULL, NULL),
  (2025, 118, NULL, '¿Cuál de las siguientes NO es una técnica propia de la terapia de activación conductual de Jacobson (2001)?:', 'Atención a la experiencia (mindfulness).', 'Programación de actividades valiosas.', 'Extinción de evitaciones.', 'Ejercicios de autocompasión.', NULL, 'd', NULL, NULL),
  (2025, 119, NULL, 'Según la terapia centrada en soluciones de De Shazer, una de las premisas básicas acerca del ser humano es que:', 'La mayoría de las personas necesitan ser instruidas para resolver sus problemas, dado su déficit de competencia.', 'Las personas buscamos asemejarnos a los demás.', 'Las conductas problemáticas reflejan deficiencias estructurales en el sistema.', 'Cada persona dispone de fortalezas y recursos que pueden activarse para promover el cambio.', NULL, 'd', NULL, NULL),
  (2025, 120, NULL, 'Según la terapia centrada en la emoción (Greenberg, 2011), el cambio terapéutico central se produce cuando el paciente:', 'Reduce la activación fisiológica mediante técnicas de relajación y control.', 'Logra distanciarse cognitivamente de sus estados afectivos intensos.', 'Reprocesa una emoción disfuncional con otra emoción más adaptativa.', 'Aprende a sustituir las emociones negativas por pensamientos racionales.', NULL, 'c', NULL, NULL),
  (2025, 121, NULL, '¿Cuál de las siguientes alternativas describe una de las características centrales de la terapia centrada en el presente (Classen, Butler y Spiegel, 2001) para el tratamiento del trastorno de estrés postraumático?:', 'Se enfoca en identificar y cuestionar directamente las creencias disfuncionales relacionadas con el trauma.', 'Se aplica principalmente en formato grupal para fomentar el apoyo social.', 'Su objetivo principal es la reducción de los síntomas de ansiedad y depresión asociados.', 'Se centra en mejorar las relaciones interpersonales utilizando la relación terapéutica como herramienta de cambio.', NULL, 'd', NULL, NULL),
  (2025, 122, NULL, 'En relación con el perfil psicopatológico específico del trastorno de estrés postraumático:', 'La reexperimentación es más característica en los supervivientes de accidentes de tráfico que en las víctimas de agresiones sexuales.', 'La evitación es un síntoma más marcado en las víctimas de agresiones sexuales, pero prácticamente ausente en el resto de las categorías.', 'Las víctimas de accidentes presentan menos evitación, pero destacan por un elevado número de síntomas de sobresalto.', 'La hiperactivación y los cambios en el estado de ánimo son característicos solo de las víctimas de terrorismo y de maltrato.', NULL, 'c', NULL, NULL),
  (2025, 123, NULL, 'Según la CIE-11, el trastorno por estrés postraumático complejo:', 'No incluye reexperimentación ni evitación, a diferencia del trastorno por estrés postraumático (TEPT).', 'Incluye los síntomas del TEPT añadiendo alteraciones en la regulación emocional, autoconcepto negativo y dificultades interpersonales.', 'Sustituye los síntomas de hiperactivación por síntomas de disociación crónica.', 'Es equivalente al TEPT con el especificador “con síntomas disociativos” del DSM-5-TR.', NULL, 'b', NULL, NULL),
  (2025, 124, NULL, 'En el trastorno por estrés postraumático, ¿cuál se considera un indicador negativo de recuperación?:', 'Haber vivido un único acontecimiento traumático relacionado con una catástrofe natural.', 'Presentar elevada reactividad fisiológica inmediata en los días posteriores al trauma.', 'Disponer de un alto apoyo social percibido tras la experiencia traumática.', 'Haber vivido una exposición repetida y prolongada a abuso sexual intrafamiliar durante la infancia.', NULL, 'd', NULL, NULL),
  (2025, 125, NULL, 'A. es despedido del trabajo tras 15 años en la empresa. En las dos semanas siguientes presenta tristeza, insomnio y preocupación constante por su situación económica. También explica que le vienen a la mente cavilaciones constantes sobre el día del despido. Según las clasificaciones diagnósticas CIE-11 y DSM-5-TR, ¿cuál es el diagnóstico más probable?:', 'Trastorno de ansiedad generalizada.', 'Trastorno de adaptación.', 'Trastorno de estrés postraumático.', 'Episodio depresivo mayor.', NULL, 'b', NULL, NULL),
  (2025, 126, NULL, 'Un hombre de 38 años acude a consulta tras sobrevivir a un accidente de tráfico grave hace 8 meses. Desde entonces, presenta recuerdos intrusivos del accidente, pesadillas frecuentes, hipervigilancia y evita conducir. También refiere elevada ansiedad cada vez que oye frenar a un coche. ¿Qué intervención se considera de primera elección?:', 'Exposición prolongada.', 'Terapia centrada en el presente.', 'Entrenamiento en inoculación de estrés.', 'Debriefing psicológico.', NULL, 'a', NULL, NULL),
  (2025, 127, NULL, '¿Cuál constituye un punto de estancamiento en la terapia de procesamiento cognitivo (CPT; Resick et al., 2012) para el tratamiento del trastorno por estrés postraumático?:', 'La tendencia a culparse a sí mismo por el evento traumático.', 'La dificultad para expresar y comunicar emociones.', 'La evitación de las situaciones que recuerden el acontecimiento traumático.', 'La dificultad para regular emociones intensas.', NULL, 'a', NULL, NULL),
  (2025, 128, NULL, 'El trastorno psicótico breve:', 'No presenta síntomas negativos, pero sí catatonía.', 'Presenta síntomas negativos, pero no catatonía.', 'Presenta síntomas positivos y negativos, pero no catatonía.', 'Presenta síntomas positivos, negativos y catatonía.', NULL, 'a', NULL, NULL),
  (2025, 129, NULL, 'Las vivencias de despersonalización en la esquizofrenia:', 'Son excepcionales y suelen aparecer en la fase aguda.', 'Son comunes, especialmente en la fase prodrómica.', 'Son comunes y suelen aparecer en la fase aguda.', 'Son habituales, sobre todo en la fase residual.', NULL, 'b', NULL, NULL),
  (2025, 130, NULL, 'En raras ocasiones, el discurso de una persona con esquizofrenia puede llegar a ser tan incomprensible que se asemeja a:', 'Una afasia sensorial.', 'Una afasia productiva.', 'Una afasia anómica.', 'Una afasia cortical.', NULL, 'a', NULL, NULL),
  (2025, 131, NULL, 'En el tratamiento de los trastornos psicóticos:', 'Durante la fase aguda se desaconsejan las intervenciones psicológicas individuales.', 'La terapia cognitivo-conductual (TCC) para la psicosis no se aplica en la fase de remisión de la sintomatología psicótica.', 'La TCC para la psicosis incluye la prevención de recaídas.', 'Durante la fase aguda se desaconsejan las intervenciones psicológicas grupales.', NULL, 'c', NULL, NULL),
  (2025, 132, NULL, 'En relación con el diagnóstico del trastorno bipolar, según el DSM-5-TR:', 'El trastorno bipolar tipo I se establece únicamente en presencia de antecedentes familiares de trastorno afectivo.', 'El trastorno bipolar tipo II requiere al menos un episodio maníaco y uno depresivo mayor.', 'El trastorno bipolar tipo I se diagnostica con al menos un episodio maníaco, haya o no episodios depresivos mayores.', 'El trastorno bipolar tipo II exige la presencia de síntomas psicóticos durante la hipomanía.', NULL, 'c', NULL, NULL),
  (2025, 133, NULL, 'En relación con el episodio hipomaníaco, según el DSM-5-TR:', 'Su duración mínima es de 4 días y no se acompaña de síntomas psicóticos.', 'Produce un deterioro funcional grave y suele requerir hospitalización.', 'Puede diagnosticarse, aunque dure solo 2 días, si hay síntomas psicóticos.', 'Su duración mínima es de 7 días y no se acompaña de síntomas psicóticos.', NULL, 'a', NULL, NULL),
  (2025, 134, NULL, 'En relación con el diagnóstico de esquizofrenia:', 'Se presenta con mayor prevalencia en áreas rurales que urbanas.', 'Los hombres presentan un inicio más precoz que las mujeres.', 'La prevalencia global supera el 3%, siendo más alta en zonas rurales y en mujeres.', 'Las mujeres evolucionan de forma más desfavorable que los hombres.', NULL, 'b', NULL, NULL),
  (2025, 135, NULL, 'Según los criterios del DSM-5-TR, el trastorno esquizoafectivo:', 'Requiere la presencia simultánea de síntomas afectivos y psicóticos durante todo el curso de la enfermedad.', 'Exige al menos 2 semanas de síntomas psicóticos sin síntomas afectivos.', 'Se clasifica dentro del espectro de los trastornos bipolares, dado su componente afectivo predominante.', 'Requiere como máximo 1 semana de síntomas psicóticos sin síntomas afectivos.', NULL, 'b', NULL, NULL),
  (2025, 136, NULL, 'Señale la FALSA en relación al trastorno neurocognitivo mayor o leve con cuerpos de Lewy (TNCCL):', 'La presencia de alucinaciones visuales es una de las características que permite establecer el diagnóstico diferencial con el trastorno neurocognitivo mayor o leve debido a Parkinson.', 'Los individuos con TNCCL están más afectados funcionalmente en comparación con los individuos con otros trastornos neurodegenerativos como el Alzheimer.', 'La sintomatología suele ser más fluctuante (cambios en los niveles de alerta y desorientación), pudiendo variar incluso a lo largo del día.', 'En la mayoría de los casos de TNCCL no hay antecedentes familiares.', NULL, 'a', NULL, NULL),
  (2025, 137, NULL, 'En relación con las intervenciones psicológicas para el trastorno de somatización en Atención Primaria (AP):', 'Los programas de formación a médicos de AP para mejorar la detección del trastorno e incorporar técnicas cognitivo-conductuales han mostrado mejoría en la calidad de vida de la persona.', 'La terapia cognitivo-conductual (TCC) individual aplicada por especialistas en AP fue superior al tratamiento habitual y la TCC grupal en la reducción de síntomas somáticos.', 'La evidencia disponible sobre los programas de formación a médicos de AP mostró resultados consistentes en la reducción de visitas médicas de estos pacientes.', 'Los ensayos clínicos con TCC en AP presentan limitaciones metodológicas que no permiten establecer su eficacia.', NULL, 'b', NULL, NULL),
  (2025, 138, NULL, 'Sobre las barreras para la detección y tratamiento de la depresión en el periodo perinatal, señale la opción INCORRECTA:', 'La ausencia de evaluaciones estandarizadas en atención primaria (AP) dificulta la detección precoz.', 'El acceso limitado a especialistas en salud mental es una de las principales barreras para recibir tratamiento adecuado.', 'El estigma asociado a los problemas de salud mental en el periodo perinatal constituye un obstáculo importante para buscar ayuda.', 'La falta de acceso a intervenciones psicológicas especializadas conduce a una mayor preferencia por el tratamiento farmacológico.', NULL, 'd', NULL, NULL),
  (2025, 139, NULL, 'Un varón de 38 años consulta en atención primaria (AP) por presentar, durante el último mes, ánimo deprimido, insomnio, fatiga, dificultad para concentrarse y pérdida de interés en las actividades habituales. Refiere buena red de apoyo social y mantiene su actividad laboral, aunque con dificultad. Explica que hace unos meses finalizó un periodo de elevada presión laboral. Niega antecedentes previos. ¿Cuál sería la orientación diagnóstica, según el DSM-5-TR, y la intervención de primera línea, según la Guía NICE (2022)?:', 'Trastorno adaptativo con ánimo depresivo; ofrecer apoyo psicoeducativo y seguimiento por AP.', 'Episodio depresivo mayor leve o moderado; iniciar tratamiento farmacológico por parte de AP, a la espera de derivación a salud mental especializada.', 'Episodio depresivo mayor leve o moderado; ofrecer un tratamiento psicológico breve por parte de psicología clínica en AP.', 'Episodio depresivo mayor moderado o grave; derivar a salud mental especializada, recomendado un tratamiento combinado de fármacos antidepresivos e intervención psicológica.', NULL, 'c', NULL, NULL),
  (2025, 140, NULL, 'Según el modelo de incertidumbre de Dugas et al. (2007), las personas con un trastorno de ansiedad generalizada:', 'Tienden a realizar respuestas de evitación conductual.', 'Tienden a realizar respuestas de evitación cognitiva.', 'Tienden igualmente a la evitación cognitiva como conductual.', 'Tienden a generan imágenes negativas catastróficas.', NULL, 'b', NULL, NULL),
  (2025, 141, NULL, '¿A qué terapia pertenece la técnica para el tratamiento de la ansiedad generalizada en la que se propone a la persona identificar su fuente de preocupación y después, sin suprimir el desencadenante, posponer todo lo posible el proceso de preocupación?:', 'El programa de reducción del estrés basado en mindfulness.', 'La terapia metacognitiva de Wells et al. (1996).', 'La terapia de aceptación y compromiso.', 'La terapia de exposición y prevención de respuesta.', NULL, 'b', NULL, NULL),
  (2025, 142, NULL, 'Señala la característica diferencial del trastorno de ansiedad generalizada respecto al resto de trastornos de ansiedad:', 'Síntomas excesivos y recurrentes que se producen en respuesta a múltiples situaciones en donde podría no haber ayuda disponible.', 'Síntomas excesivos e inesperados que no se limitan a estímulos o situaciones particulares.', 'Síntomas que se centran en múltiples eventos cotidianos percibidos como difíciles de controlar.', 'Síntomas físicos y cognitivos como palpitaciones, sudoración, temblores, dificultad para respirar, y la sensación de falta de control.', NULL, 'c', NULL, NULL),
  (2025, 143, NULL, 'La técnica de intervención denominada enraizamiento (grounding) se utiliza principalmente en el tratamiento de:', 'Los trastornos disociativos.', 'Los trastornos psicóticos.', 'El trastorno de ansiedad social.', 'El trastorno límite de personalidad.', NULL, 'a', NULL, NULL),
  (2025, 144, NULL, '¿Cuáles son los 4 ejes del modelo BASK de Braun (1988)?:', 'Conducta, afecto, sensación somática y conocimiento.', 'Conducta, afecto, memoria biográfica y conocimiento.', 'Conducta, afecto, memoria biográfica y significados.', 'Conducta, afecto, sensación somática y significados.', NULL, 'a', NULL, NULL),
  (2025, 145, NULL, 'Según el modelo de la terapia interpersonal y de ritmo social (Klerman et al., 2007) para el trastorno bipolar, las recurrencias se producen por la interacción de tres factores de vulnerabilidad. El primero se refiere a las alteraciones en los ritmos sociales, ¿cuáles son los otros dos factores de vulnerabilidad?:', 'Eventos vitales estresantes y falta de adherencia al tratamiento farmacológico.', 'Conflictos interpersonales y el abuso de alcohol u otras drogas.', 'Eventos vitales traumáticos (como la pérdida de un ser querido o problemas financieros) y falta de apoyo social o familiar.', 'El consumo de sustancias y el estrés intenso.', NULL, 'a', NULL, NULL),
  (2025, 146, NULL, 'Según el metaanálisis de Turner et al. (2018), el entrenamiento en habilidades sociales aplicado a personas con trastornos psicóticos produce mejoras en:', 'Funcionamiento social y síntomas psicóticos.', 'Funcionamiento social y de la cognición social.', 'Síntomas positivos y psicopatología general.', 'Síntomas negativos y psicopatología general.', NULL, 'd', NULL, NULL),
  (2025, 147, NULL, 'La CIE-11 reconoce dos adicciones comportamentales:', 'El trastorno por juego de apuestas y el trastorno por uso de videojuegos.', 'La adicción a videojuegos y las compras compulsivas.', 'El trastorno de juego patológico y las compras compulsivas.', 'El trastorno por juego de apuestas y la adicción a las redes sociales.', NULL, 'a', NULL, NULL),
  (2025, 148, NULL, 'El trastorno de juego (juego patológico o ludopatía):', 'Tiene una prevalencia que se sitúa entre el 46% en España.', 'Se caracteriza por un perfil de personalidad disfuncional con baja impulsividad y elevada autodirección.', 'Es la primera y única adicción comportamental formalmente reconocida en el DSM-5-TR.', 'Debuta a menor edad en las mujeres que en los hombres, aunque su desarrollo suele ser más lento (efecto telescoping).', NULL, 'c', NULL, NULL),
  (2025, 149, NULL, '¿Qué es la falacia del jugador?:', 'Es un sesgo cognitivo de los jugadores en el que aparecen eventos que vienen fácilmente a la memoria, aunque eso no tenga nada que ver con su probabilidad de aparición real.', 'Consiste en pensar que se tiene alguna suerte de habilidad o estrategia que permite modificar la probabilidad de aparición de un evento y gracias a ello poder ganar la apuesta.', 'Es un error cognitivo en el que los jugadores piensan que su forma de ser o comportarse es mejor que la de los demás.', 'Es un sesgo cognitivo característico de los jugadores que consiste en no tener en cuenta la independencia entre sucesos aleatorios.', NULL, 'd', NULL, NULL),
  (2025, 150, NULL, 'C. no presenta episodios maníacos, pero participa en juegos de apuestas que le provocan deterioro y malestar clínicamente significativo. En la entrevista se constata la presencia de 6 de los 9 criterios diagnósticos del trastorno por juego. Además, refiere síntomas continuos y el cumplimiento de los criterios durante varios años. Según el DSM-5-TR, ¿cuál sería el diagnóstico más adecuado?:', 'Juego patológico persistente moderado.', 'Juego patológico episódico grave.', 'Juego patológico persistente grave.', 'Juego patológico episódico moderado.', NULL, 'a', NULL, NULL),
  (2025, 151, NULL, 'Si en un informe clínico aparece el diagnóstico de juego patológico grave en remisión inicial, según el DSM-5-TR significa que no ha cumplido ninguno de los criterios de juego patológico:', 'Durante un mínimo de 6 meses, pero sin llegar a 12 meses.', 'Durante un mínimo de 3 meses, pero sin llegar a 12 meses.', 'Durante un período de 12 meses o más.', 'Durante un período de 24 meses o más.', NULL, 'b', NULL, NULL),
  (2025, 152, NULL, 'En comparación con la población general, las personas con compra compulsiva presentan:', 'Mayores niveles de impulsividad emocional (urgencia positiva y negativa) y cognitiva (falta de perseverancia y de premeditación).', 'Menores niveles de impulsividad emocional (urgencia negativa) y cognitiva (falta de perseverancia y de premeditación).', 'Mayores niveles de funcionamiento ejecutivo y atención selectiva.', 'Mayores niveles de impulsividad emocional (urgencia positiva y negativa) y no presentan diferencias en la impulsividad cognitiva (perseverancia y premeditación).', NULL, 'a', NULL, NULL),
  (2025, 153, NULL, '¿Qué tipos de vulnerabilidades incluye el modelo de Barlow (2000)?:', 'Vulnerabilidad genética, vulnerabilidad biológica y vulnerabilidad psicológica.', 'Vulnerabilidad biológica general, vulnerabilidad biológica específica y vulnerabilidad psicológica.', 'Vulnerabilidad biológica, vulnerabilidad psicológica general y vulnerabilidad psicológica específica.', 'Vulnerabilidad social, vulnerabilidad biológica y vulnerabilidad psicológica.', NULL, 'c', NULL, NULL),
  (2025, 154, NULL, 'Según Bieling et al. (2006), ¿cuál sería un criterio relevante para incluir a personas con trastorno de pánico (TP) y/o agorafobia en un grupo de tratamiento de base cognitivo conductual?:', 'Que la persona realice atribuciones orgánicas de sus síntomas.', 'Que presente un cuadro de agorafobia muy grave.', 'Que, aunque no cumpla todos los criterios diagnósticos de TP y/o agorafobia, presente ataques de pánico de forma recurrente.', 'Que no existan otros trastornos comórbidos que requieran un tratamiento previo (p. ej., abuso de sustancias o depresión).', NULL, 'd', NULL, NULL),
  (2025, 155, NULL, 'La respiración lenta o diafragmática es un componente utilizado con frecuencia en el tratamiento cognitivo-conductual del trastorno de pánico. Indique la afirmación correcta:', 'Es un componente necesario del tratamiento, ya que en todas las crisis en contexto natural se produce hiperventilación e hipocapnia.', 'Conviene prevenir su uso como conducta de evitación: no se trata de eliminar la ansiedad, sino de regularla para no sentirse desbordado.', 'Ha mostrado mejorar sistemáticamente los resultados del tratamiento de exposición cuando se aplican conjuntamente ambos componentes.', 'Requiere una evaluación y entrenamiento individualizado, por lo que se desaconseja su uso en tratamientos grupales.', NULL, 'b', NULL, NULL),
  (2025, 156, NULL, '¿Cuál de las siguientes es una respuesta de seguridad o estrategia de afrontamiento característica de una persona que sufre hipocondría para huir del estado ansioso?:', 'Evitar encontrarse con personas conocidas para que no se fijen en su aspecto.', 'Ducharse a oscuras para no detectar posibles signos o síntomas en el cuerpo.', 'Dejar de buscar información médica en internet ante cualquier síntoma.', 'Lavarse muy frecuentemente las manos para no sentirse sucio.', NULL, 'b', NULL, NULL),
  (2025, 157, NULL, 'En relación con la eliminación de las conductas de seguridad en el tratamiento cognitivo-conductual de la hipocondría, señale la respuesta INCORRECTA:', 'Deben comenzar a eliminarse en la última fase del tratamiento, en caso contrario el riesgo de abandono es muy elevado.', 'Debe contarse con la persona para seleccionar las conductas que se compromete eliminar, ya sea por el menor nivel de ansiedad y/o por el alto grado de interferencia que le ocasionan.', 'Debe comenzarse por conductas observables y de control voluntario, frente a conductas encubiertas o que implican a otros.', 'Además de la eliminación directa, puede utilizarse como estrategia realizar experimentos conductuales.', NULL, 'a', NULL, NULL),
  (2025, 158, NULL, 'Respecto a la reestructuración cognitiva en el tratamiento de las personas con hipocondría:', 'La técnica de la doble columna no es un procedimiento aconsejado para el tratamiento de las cogniciones hipocondriacas.', 'Una vez que se ha establecido una buena relación terapéutica, se debe debatir directamente el contenido de la amenaza.', 'Se pretende que comprendan que no son los síntomas ni los pensamientos intrusivos sobre la posibilidad percibida de padecer una enfermedad lo que causa directamente el problema.', 'Los experimentos conductuales deben plantearse una vez que las principales valoraciones disfuncionales han mejorado mediante el desafío verbal.', NULL, 'c', NULL, NULL),
  (2025, 159, NULL, 'Según el modelo alternativo del DSM-5-TR, los rasgos patológicos de personalidad se organizan en los siguientes grandes ámbitos:', 'Afecto negativo, Desapego, Antagonismo, Desinhibición y Psicoticismo.', 'Identidad, Autodirección, Empatía e Intimidad.', 'Manipulación, Insensibilidad, Engaño y Hostilidad.', 'Inestabilidad Emocional, Psicoticismo, Impulsividad, Insensibilidad y Evitación.', NULL, 'a', NULL, NULL),
  (2025, 160, NULL, '¿Qué característica puede distinguir al trastorno de personalidad límite del histriónico en un diagnóstico diferencial?:', 'La búsqueda de atención /afecto.', 'Un patrón de emociones que cambian rápidamente.', 'Los arrebatos coléricos y la autodestructividad.', 'La conducta manipuladora.', NULL, 'c', NULL, NULL),
  (2025, 161, NULL, 'Entre los componentes y objetivos de la terapia basada en la mentalización para el trastorno límite (Bateman y Fonagy, 2004), la técnica “Párate, Escucha y Mira”:', 'Se utiliza para preparar el final de la terapia, atendiendo a la sensación de pérdida.', 'Se utiliza en la fase inicial de la terapia, en formato individual, y tiene el objetivo de involucrar al paciente en el tratamiento.', 'Se realiza en formato individual o grupal durante la fase media, con el objetivo de fomentar la mentalización.', 'Sirve para contrastar la percepción del paciente y el terapeuta sobre la relación, y se utiliza fundamentalmente en la fase final.', NULL, 'c', NULL, NULL),
  (2025, 162, NULL, '¿Cuál de las siguientes organizaciones de significado personal NO fue incluida por V. Guidano en su modelo de psicoterapia cognitiva posracionalista?:', 'Fóbica.', 'Obsesiva.', 'Narcisista.', 'Depresiva.', NULL, 'c', NULL, NULL),
  (2025, 163, NULL, '¿Qué estrategia de prevención selectiva de la conducta suicida cuenta con un grado de evidencia sólido?:', 'Tratamiento psicoterapéutico y farmacológico del trastorno depresivo.', 'Restricción del acceso a medios letales.', 'Entrenamiento a guardianes o gatekeepers.', 'Formación a profesionales sanitarios.', NULL, 'a', NULL, NULL),
  (2025, 164, NULL, '“Ganando, siempre ganando. Si no ganas, es que no lo intentas lo suficiente. Yo no necesito que nadie me diga lo que está bien o mal; la gente corriente se pone límites porque son mediocres. Los demás deberían admirarte, no frenarte. Si tus amigos o tu familia no te apoyan, mejor prescinde de ellos: no entienden tu nivel”. Según el modelo alternativo del DSM-5-TR para los trastornos de personalidad y los elementos del funcionamiento de la personalidad, ¿a qué trastorno específico de la personalidad podría pertenecer este discurso?:', 'Antisocial.', 'Evitativa.', 'Narcisista.', 'Límite.', NULL, 'c', NULL, NULL),
  (2025, 165, NULL, 'Durante una hospitalización, un paciente con antecedentes de conflictos familiares presenta un episodio súbito de mutismo, flexibilidad cérea y ausencia de respuesta a estímulos dolorosos, pese a un EEG normal. El día anterior había discutido con sus padres, quienes le habían negado dinero para independizarse. El cuadro cede bruscamente cuando llega la hora de la comida. ¿Cuál es el diagnóstico más probable?:', 'Estupor disociativo.', 'Estupor orgánico.', 'Estupor catatónico.', 'Simulación.', NULL, 'd', NULL, NULL),
  (2025, 166, NULL, '¿Cuál de las siguientes afirmaciones es correcta respecto de la Parent–Infant Psychotherapy (PIP)?:', 'Propone la App Padre (atención, toma de perspectiva y empatía) como herramienta de intervención.', 'Incorpora una perspectiva transgeneracional, abordando cómo las experiencias tempranas y los conflictos no resueltos de los progenitores influyen en el vínculo con el bebé.', 'Ha demostrado una mayor eficacia en población preescolar (3-6 años) que en la primera infancia (0-3 años).', 'Centra su intervención en el entrenamiento de habilidades de afrontamiento y manejo conductual de los padres.', NULL, 'b', NULL, NULL),
  (2025, 167, NULL, '¿Cuál de las siguientes técnicas permite la elaboración simbólica del trauma en niños y adolescentes?:', 'La reexperimentación emocional.', 'La técnica 5-4-3-2-1.', 'El escaneo corporal.', 'La caja de arena.', NULL, 'd', NULL, NULL),
  (2025, 168, NULL, 'En cuanto a la participación de la familia en la intervención con conductas autolesivas y suicidas en la adolescencia:', 'Los familiares deben participar en la intervención.', 'Si el adolescente expresa su deseo de mantener la confidencialidad, no se debe involucrar a la familia, salvo que se produzca una tentativa de suicidio grave.', 'La información a la familia debe incluir el detalle de los métodos autolesivos para mejorar la supervisión y la adherencia al tratamiento.', 'La intervención familiar se considera contraproducente cuando los factores de conflicto parental o sobreinvolucramiento emocional son antecedentes del síntoma, por lo que en estos casos se recomienda el trabajo individual.', NULL, 'a', NULL, NULL),
  (2025, 169, NULL, 'En relación con los programas de intervención temprana en el trastorno del espectro autista (TEA), ¿cuál describe con mayor precisión el Programa HANEN?:', 'Es un modelo de intervención temprana basado en el desarrollo y aplicado por el terapeuta en contextos naturales, que combina estrategias conductuales y evolutivas para promover la atención conjunta y el lenguaje.', 'Es una intervención de tipo mixto (conductual y comunicativo) centrada en mejorar la generalización del aprendizaje mediante sesiones conjuntas entre terapeuta y niño, bajo la metodología del modelo SCERTS.', 'Es un programa de base conductual que utiliza reforzadores naturales y análisis funcional de la conducta para disminuir comportamientos inadecuados y aumentar los adaptativos.', 'Se centra en el entrenamiento de los progenitores para que estos actúen como principales agentes de cambio, tras un periodo inicial de formación profesional.', NULL, 'd', NULL, NULL),
  (2025, 170, NULL, 'Acude a la consulta un niño de 5 años diagnosticado trastorno por déficit de atención/hiperactividad (TDAH), ¿qué tipo de tratamiento es el más recomendado?:', 'Tratamiento con neurofeedback.', 'Tratamiento farmacológico.', 'Entrenamiento en habilidades sociales.', 'Tratamiento conductual con pautas para los padres o cuidadores.', NULL, 'd', NULL, NULL),
  (2025, 171, NULL, 'El Cool Little Kids:', 'Es un programa dirigido a niños con trastornos de conducta.', 'Suele aplicarse a niños de entre 10 y 14 años.', 'Es un tratamiento para la ansiedad con una orientación psicodinámica.', 'Está especialmente dirigido a niños con un temperamento inhibido.', NULL, 'd', NULL, NULL),
  (2025, 172, NULL, 'Un adolescente de 15 años acude a consulta por una preocupación generalizada sobre distintas áreas (familia, escuela, amigos), que genera malestar significativo y deterioro funcional:', 'La exposición en vivo sería la primera elección de tratamiento.', 'Se le podría ofrecer el programa No Worries! en formato grupal, orientado al manejo de la ansiedad generalizada.', 'La exposición en imaginación sería la primera elección de tratamiento.', 'No existen tratamientos con suficiente evidencia empírica para este tipo de trastorno.', NULL, 'b', NULL, NULL),
  (2025, 173, NULL, '¿Cuál de los siguientes NO se considera un factor de riesgo socioambiental o contextual de la conducta suicida en población infantojuvenil?:', 'Abandono escolar.', 'Baja motivación académica.', 'Absentismo escolar.', 'Mala relación con los iguales.', NULL, 'b', NULL, NULL),
  (2025, 174, NULL, 'Los efectos de la disfasia evolutiva o trastorno específico del lenguaje:', 'Son ausentes o muy escasos a partir de la adolescencia, si el paciente ha recibido atención logopédica antes de cumplir los 6 años.', 'Por lo general, continúan en la adolescencia y en la edad adulta.', 'Implican de forma directa a la comprensión del lenguaje, siendo infrecuente la afectación de aspectos expresivos.', 'Implican en mayor medida a los aspectos fonológicos que a los pragmáticos del lenguaje.', NULL, 'b', NULL, NULL),
  (2025, 175, NULL, '¿Qué hallazgo evolutivo ha sido reportado al comparar la presentación clínica del trastorno de ansiedad generalizada entre niños y adolescentes?:', 'Los niños menores de 12 años tienen mayor probabilidad de experimentar ideación suicida y síntomas cognitivos que los adolescentes.', 'El criterio diagnóstico esencial de una preocupación excesiva resulta inadecuado en los niños, ya que antes de la pubertad el trastorno de ansiedad generalizada se manifiesta únicamente a través de quejas somáticas y problemas de sueño.', 'Ambos grupos de edad presentan índices similares de síntomas específicos, pero los adolescentes exhiben un mayor número de síntomas totales y niveles más altos de ansiedad y depresión.', 'Es infrecuente antes de la adolescencia y sólo se diagnostica en niños cuando la sintomatología ha persistido durante al menos 12 meses.', NULL, 'c', NULL, NULL),
  (2025, 176, NULL, 'El patrón de apego caracterizado por alta ansiedad relacional y alta comodidad por la cercanía en las relaciones se denomina:', 'Estilo seguro.', 'Estilo preocupado-ambivalente.', 'Estilo rechazante-evitador.', 'Estilo temeroso-desorganizado.', NULL, 'b', NULL, NULL),
  (2025, 177, NULL, '¿Cuál de las siguientes afirmaciones describe correctamente la manifestación de la sintomatología depresiva en la infancia y adolescencia?:', 'Los síntomas cognitivos, como los pensamientos de inutilidad y la desesperanza, son más frecuentes en los niños más pequeños que en los adolescentes.', 'La tristeza puede ser sustituida por sentimientos de irritabilidad o enfado, siendo esto un síntoma clave en la depresión infantojuvenil.', 'Las técnicas de autoinforme (cuestionarios, inventarios) pueden aplicarse con elevada fiabilidad en niños a partir de 3 años.', 'En la infancia predominan las manifestaciones en el sistema de respuesta cognitivo, mientras que con el paso de los años adquieren relevancia los sistemas psicofisiológicos y motores.', NULL, 'b', NULL, NULL),
  (2025, 178, NULL, '¿Cuál de las siguientes afirmaciones describe correctamente la situación de la terapia cognitivo conductual (TCC) respecto a la depresión infantil y adolescente?:', 'Para la depresión infantil no hay ningún tratamiento con nivel 1 o nivel 2 de apoyo empírico, pero la TCC es un tratamiento bien establecido para la depresión adolescente.', 'La TCC goza del mismo nivel de apoyo empírico (nivel 1: bien establecido) para la depresión tanto en niños como en adolescentes.', 'La TCC individual es un tratamiento bien establecido para la depresión infantil, mientras que en adolescentes se reserva la TCC de grupo o la terapia interpersonal.', 'La TCC es solo un tratamiento posiblemente eficaz (nivel 3) para la depresión adolescente, mientras que la medicación (fluoxetina) cuenta con el nivel 1 de apoyo empírico.', NULL, 'a', NULL, NULL),
  (2025, 179, NULL, '¿Cuál es la edad cronológica mínima y la frecuencia requerida de los episodios para diagnosticar encopresis, según los criterios diagnósticos habituales (DSM-5-TR)?:', 'Mínimo de 6 años y al menos dos episodios al mes durante 3 meses consecutivos.', 'Mínimo de 5 años y al menos un episodio a la semana durante 6 meses.', 'Mínimo de 4 años y al menos un episodio al mes durante 3 meses consecutivos.', 'Mínimo de 4 años y al menos dos episodios a la semana durante 1 mes.', NULL, 'c', NULL, NULL),
  (2025, 180, NULL, '¿Cuál es la técnica conductual multicomponente más aceptada para establecer la defecación regular en el retrete, y en qué principio de aprendizaje se basa fundamentalmente el tratamiento de la encopresis?:', 'El biofeedback anorrectal para el control de la musculatura, cuyo mecanismo principal es el contracondicionamiento.', 'El entrenamiento en hábitos defecatorios, que se fundamenta en el condicionamiento operante.', 'La alarma fecal para el control de estímulos, basada en el condicionamiento clásico.', 'La práctica positiva contingente para reforzar el comportamiento de limpieza.', NULL, 'b', NULL, NULL),
  (2025, 181, NULL, 'Sobre la discapacidad intelectual, ¿cuál de estas afirmaciones es cierta?:', 'No es posible establecer la causa de la discapacidad intelectual en aproximadamente el 50% de los casos.', 'La prevalencia se mantiene estable a nivel mundial.', 'Se considera que un 75% de la población presenta formas leves y un 25% formas más graves.', 'En la discapacidad intelectual adquirida la afectación se presenta de forma insidiosa.', NULL, 'a', NULL, NULL),
  (2025, 182, NULL, 'Con respecto a la esquizofrenia infantil:', 'El diagnóstico diferencial con el trastorno del espectro autista (TEA) se establece por la presencia de creencias e intereses atípicos.', 'El inicio suele producirse tras un periodo de desarrollo normal o casi normal.', 'Las nuevas clasificaciones diagnósticas (CIE-11 y DSM-5-TR) diferencian la esquizofrenia infantil de la del adulto como categorías separadas.', 'Los síntomas psicóticos son similares en contenido y forma a los observados en la esquizofrenia del adulto.', NULL, 'b', NULL, NULL),
  (2025, 183, NULL, 'El trastorno de la comunicación social (pragmática):', 'Se puede acompañar de problemas de conducta y trastornos específicos del aprendizaje.', 'Si se cumplen también los criterios diagnósticos para el trastorno del espectro autista, se deben diagnosticar ambos trastornos.', 'La característica más habitual es la falta de competencia para el uso social del lenguaje verbal, pero no el no verbal.', 'Aparecen también patrones restrictivos y repetitivos de comportamiento.', NULL, 'a', NULL, NULL),
  (2025, 184, NULL, 'En el trastorno negativista desafiante:', 'El inicio temprano se asocia a una mayor estabilidad del cuadro y a un mejor pronóstico.', 'Es más prevalente en varones durante la infancia y la adolescencia.', 'Los inmigrantes de primera generación y los refugiados tienen más riesgo de presentar síntomas.', 'La severidad parental como factor de riesgo está más asociada a las chicas que a los chicos.', NULL, 'd', NULL, NULL),
  (2025, 185, NULL, '¿En cuál de las siguientes intervenciones para el abordaje de los problemas de conducta en la infancia el juego constituye un contexto terapéutico central y estructurado para el entrenamiento parental?:', 'El programa de parenting triple P positivo.', 'The incredible years.', 'La terapia de interacción padres-hijos (PCIT).', 'El entrenamiento en Manejo para Padres Oregón (PMT-O).', NULL, 'c', NULL, NULL),
  (2025, 186, NULL, 'En el modelo de Patterson (1982; 1992) sobre la coerción, ¿cuál es el mecanismo central que explica el mantenimiento de conductas desafiantes en un niño?:', 'La falta de consecuencias negativas para el niño.', 'Un déficit en las habilidades lingüísticas del niño.', 'El exceso de control parental hacia el niño.', 'El refuerzo mutuo entre las conductas del niño y los padres.', NULL, 'd', NULL, NULL),
  (2025, 187, NULL, 'En relación al establecimiento de la alianza terapéutica en niños y adolescentes con problemas de conducta, ¿cuál de las siguientes afirmaciones es INCORRECTA?:', 'La desconfianza inicial hacia el terapeuta puede entenderse como una reacción esperable y adaptativa.', 'El terapeuta debe fomentar la confianza del menor asegurando la confidencialidad y privacidad de todas sus conductas.', 'El terapeuta debe tolerar el silencio o la evitación inicial sin precipitar interpretaciones sobre la motivación del menor.', 'El terapeuta debe priorizar la sintonía emocional compartida antes que las explicaciones y la comunicación verbal directa.', NULL, 'b', NULL, NULL),
  (2025, 188, NULL, 'Según el DSM-5-TR, en el trastorno de apego reactivo:', 'Es necesario que el niño tenga una edad de desarrollo de al menos 5 años para realizar el diagnóstico.', 'Se permite especificar el subtipo (evitativo, desinhibido o ambivalente).', 'Es un trastorno poco frecuente, incluso en los casos de negligencia grave.', 'Se puede diagnosticar sin la presencia de un patrón externo de cuidado insuficiente.', NULL, 'c', NULL, NULL),
  (2025, 189, NULL, 'Según el DSM-5-TR, el diagnóstico diferencial entre el trastorno negativista desafiante (TND) y el trastorno de desregulación disruptiva del estado de ánimo (TDDEA):', 'Los síntomas afectivos del TDDEA son relativamente raros en los niños con TND.', 'Los rasgos claves del TND son los accesos de cólera y la persistencia del ánimo irascible entre los ataques.', 'Se recomienda diagnosticar los dos trastornos si un niño cumple los criterios para ambos.', 'El diagnóstico de TND requiere la presencia de los síntomas en, al menos, dos contextos diferentes.', NULL, 'a', NULL, NULL),
  (2025, 190, NULL, 'Respecto a las diferencias de género en adolescentes con consumo de sustancias:', 'Los chicos con problemas de abuso de sustancias presentan una mayor influencia frente al consumo que realizan los iguales.', 'El progreso desde el consumo experimental o inicial hasta el consumo problemático sucede de forma más rápida en las chicas.', 'En los recursos de tratamiento para adolescentes con esta problemática, la representación de hombres y mujeres que acuden reflejan la prevalencia de consumo en esta población.', 'Los chicos con problemas de consumo de sustancias presentan habitualmente más problemas psicológicos comórbidos.', NULL, 'b', NULL, NULL),
  (2025, 191, NULL, 'Respecto a la terapia dialéctico conductual para adolescentes (DBT-A; Miller et al., 2007):', 'No se ha demostrado que a largo plazo se mantenga la menor frecuencia de autolesiones.', 'La desesperanza es una variable moderadora del efecto positivo y significativo de la DBT-A.', 'Tiene como objetivo principal reducir la ideación autolítica a través de técnicas de reestructuración cognitiva.', 'Es una intervención breve diseñada específicamente para disminuir el riesgo de intentos de suicidio en adolescentes después del alta hospitalaria.', NULL, 'b', NULL, NULL),
  (2025, 192, NULL, 'Una diferencia fundamental entre el consumo de sustancias en población adulta y adolescente es que:', 'En la adolescencia, hay una menor experiencia tanto de las consecuencias negativas asociadas al consumo, como de los reforzadores.', 'En la edad adulta, la percepción de riesgo y de gravedad del patrón de consumo es menor que en la adolescencia.', 'En la adolescencia, hay una mayor búsqueda de ayuda e intención de cambio del consumo problemático que en la edad adulta.', 'En la edad adulta, hay una mayor tasa de abandonos de los tratamientos que en la adolescencia.', NULL, 'a', NULL, NULL),
  (2025, 193, NULL, 'Teniendo en cuenta la teoría de Asch, ¿cómo se denomina al efecto de adaptar la información contradictoria que recibimos de una persona a la impresión previa que teníamos de ella?:', 'Efecto de recencia.', 'Efecto de asimilación de atributos.', 'Efecto de inferencia previa.', 'Efecto de primacía.', NULL, 'd', NULL, NULL),
  (2025, 194, NULL, '¿Cuál de los siguientes factores puede explicar la facilitación social?:', 'El liderazgo.', 'La desconexión moral.', 'La aprehensión por la evaluación.', 'La atracción social.', NULL, 'c', NULL, NULL),
  (2025, 195, NULL, 'Las teorías de la acción razonada y de la conducta planeada para explicar el vínculo entre la actitud y la conducta señalan cuatro factores que intervienen en la conducta. ¿Cuáles son dichos factores?:', 'Las actitudes hacia la conducta, las normas subjetivas, el control conductual percibido y la intención conductual.', 'La motivación, la accesibilidad de la actitud, la recompensa intrínseca y la autoeficacia.', 'La fuerza de la actitud, la planificación de la conducta, la autopercepción y la identidad social.', 'El conocimiento previo, la fuerza de la actitud, la autoidentidad y la presión social.', NULL, 'a', NULL, NULL),
  (2025, 196, NULL, '¿Cómo se denomina a la tendencia a almacenar o recordar información positiva cuando la persona se halla en estado de ánimo positivo y de almacenar o recordar información negativa cuando se halla en estado de ánimo negativo?:', 'Hipótesis del recuerdo dependiente del estado de ánimo.', 'Hipótesis del recuerdo congruente con el estado de ánimo.', 'Hipótesis del recuerdo contaminante.', 'Hipótesis del recuerdo reactante.', NULL, 'b', NULL, NULL),
  (2025, 197, NULL, 'En relación con la agresión, ¿qué teoría plantea que la activación producida en una situación pueda persistir e intensificar las reacciones emocionales ocurridas en situaciones posteriores?:', 'Teoría de la transferencia de la excitación (Zillmann, 1977, 1988).', 'Teoría de la agresión desplazada (da Gloria et al., 1994).', 'Teoría de la frustración-agresión (Dollar et al., 1939).', 'Teoría general de la agresión humana (Andreson et al., 1996).', NULL, 'a', NULL, NULL),
  (2025, 198, NULL, '¿En qué consiste el efecto espectador cuando se hace referencia al comportamiento prosocial?:', 'Es más probable que una persona espectadora ayude en una emergencia, si siente compasión por la persona que necesita ayuda.', 'Es más probable que una persona espectadora ayude en una emergencia, si considera que ello le permitirá librarse de un estado emocional negativo.', 'Es más probable que una persona espectadora acompañada de otras ayude en una emergencia, que cuando está sola.', 'Es más probable que una persona espectadora solitaria ayude en una emergencia, que cuando está acompañada de otras.', NULL, 'd', NULL, NULL),
  (2025, 199, NULL, 'Según Jones y Niesbett (1972), ¿cómo se denomina a la tendencia a atribuir nuestras propias conductas a factores externos y las de los demás a factores internos?:', 'Efecto de la comparación atribucional.', 'Efecto de la polarización atribucional.', 'Efecto del locus de control.', 'Efecto actor-observador.', NULL, 'd', NULL, NULL),
  (2025, 200, NULL, 'El saber que un miembro del propio endogrupo ha establecido una relación estrecha con un miembro del exogrupo puede mejorar las actitudes hacia el exogrupo y reducir los prejuicios hacia éste. ¿Cómo se denomina a este efecto?:', 'Efecto de vinculación.', 'Efecto del contacto extendido.', 'Efecto de distintividad óptima.', 'Efecto de identidad endogrupal.', NULL, 'b', NULL, NULL),
  (2025, 201, NULL, 'Según lo establecido en los Standards for Educational and Psychological Testing (AERA, APA y NCME, 2014), indique cuál de las siguientes alternativas NO se considera una evidencia de validez:', 'Evidencias basadas en el contenido.', 'Evidencias basadas en los procesos de respuesta.', 'Evidencias basadas en la fiabilidad de las puntuaciones.', 'Evidencias basadas en la relación con otras variables.', NULL, 'c', NULL, NULL),
  (2025, 202, NULL, '¿Cuál es la función principal que se atribuye al sistema parvocelular del núcleo geniculado lateral, según su organización laminar?:', 'Recibir la totalidad de las aferencias del ojo ipsilateral en las capas 1, 4 y 6.', 'Es el centro fundamental para la coordinación de la información sensorial olfatoria.', 'Es responsable del análisis de los detalles finos de la imagen y de la percepción del color.', 'Se especializa en la sensibilidad al movimiento y en la percepción de las características generales del estímulo.', NULL, 'c', NULL, NULL),
  (2025, 203, NULL, 'La familia de J. está desbordada. En los últimos meses ha experimentado dificultades de rendimiento en su trabajo habitual de asesor financiero, teniendo que ser supervisado y reasignado a tareas más simples. Se ha separado de su mujer y ha perdido miles de euros en una supuesta relación sentimental por internet, que sigue considerando real. Ha desarrollado conductas compulsivas (fumar y consumir refrescos) y muestra frialdad emocional con su familia. Según el DSM-5-TR, ¿cuál es el diagnóstico de J.?:', 'Trastorno neurocognitivo frontotemporal mayor probable.', 'Trastorno neurocognitivo frontotemporal leve probable.', 'Trastorno neurocognitivo frontotemporal mayor posible.', 'Trastorno neurocognitivo frontotemporal leve posible.', NULL, 'c', NULL, NULL),
  (2025, 204, NULL, 'En el tratamiento de la bulimia nerviosa:', 'No hay evidencia a favor del tratamiento con enfoques de autoayuda.', 'El tratamiento tiene un efecto significativo sobre el peso corporal.', 'La mayoría de los pacientes pueden ser tratados a nivel ambulatorio.', 'Las terapias de tercera generación se consideran tratamientos empíricamente validados para la bulimia nerviosa.', NULL, 'c', NULL, NULL),
  (2025, 205, NULL, 'En el proceso de duelo, los menores entre 6 y 9 años:', 'Aún no pueden entender la universalidad de la muerte, por lo que pueden hacer preguntas inapropiadas o muy repetitivas.', 'Entienden que el concepto de muerte es universal, irreversible y permanente, aunque pueden tratar de mantener una relación con el difunto a través de la fantasía.', 'Suelen entender que no pueden hacer nada para detener la muerte, que es irreversible y universal, pero pueden no aceptar la posibilidad de que les puede ocurrir a sus familiares o a ellos.', 'Los niños se encuentran en la etapa del egocentrismo y del pensamiento mágico y pueden creer que, si hacen algo o lo desean mucho, la persona fallecida puede volver.', NULL, 'c', NULL, NULL),
  (2025, 206, NULL, 'Cuando juego al golf, necesito hacer algunos golpes para meter la pelota en el hoyo, aunque en un primer momento, no sé con certeza qué número de golpes. ¿A qué programa de reforzamiento estoy sometido?:', 'Razón fija.', 'Razón variable.', 'Intervalo variable.', 'Intervalo fijo.', NULL, 'b', NULL, NULL),
  (2025, 207, NULL, '¿Qué instrumento permite explorar distintos tipos de conductas adictivas relacionadas con el consumo de sustancias, el juego de apuestas o la adicción a los videojuegos?:', 'MULTICAGE CAD-4 de Pedrero y cols. (2007).', 'Brief Problem Gambling Screen (BPGS) de Volberg y Williams (2011).', 'Internet Gaming Disorder-20 Test (IGD-20) de Pontes y cols. (2014).', 'Problematic Video Game Playing Scale (PVP) de Salguero y Morán (2002).', NULL, 'a', NULL, NULL),
  (2025, 208, NULL, '¿Cuál de las siguientes influencias teóricas constituye un antecedente de la corriente intersubjetivista del psicoanálisis (R. Stolorow, G. Atwood)?:', 'El modelo lingüístico de J. Lacan.', 'La psicología del self de H. Kohut.', 'La teoría estructural de la personalidad de O. Kernberg.', 'El trabajo de lo negativo de A. Green.', NULL, 'b', NULL, NULL),
  (2025, 209, NULL, 'Según la teoría del razonamiento moral de Kohlberg (Kohlberg, 1969; Lickona, 1976), ¿en qué etapa del desarrollo moral se encuentra una persona que tiende a evaluar la acción del otro de acuerdo con sus motivos e intenciones, tomando en cuenta las circunstancias?:', 'Etapa de propósito instrumental e intercambio.', 'Etapa de mantenimiento de las relaciones mutuas y aprobación de otros.', 'Etapa de interés social y conciencia.', 'Etapa de moralidad de contrato o de los derechos individuales.', NULL, 'b', NULL, NULL),
  (2025, 210, NULL, '¿Cuál de las siguientes afirmaciones sobre el proceso de evaluación clínica en el maltrato infantil es correcta?:', 'De cara a favorecer la validez, la evaluación debe centrarse en el análisis clínico de los factores individuales, siendo la valoración de las variables familiares y contextuales competencia del sistema de protección.', 'Entre los objetivos de la evaluación clínica se incluye analizar la coherencia y la credibilidad del relato del menor para determinar el grado de fiabilidad de su testimonio.', 'Para garantizar la objetividad del proceso, el clínico debe priorizar instrumentos estandarizados, evitando el uso de recursos expresivos o proyectivos que puedan inducir sesgos interpretativos.', 'La decisión de entrevistar a los cuidadores o familiares deberá realizarse en función de la valoración clínica del caso y de las dinámicas relacionales observadas.', NULL, 'd', NULL, NULL);
